static int ST_YInt(const YAML::Node& node, const char* key, int def) { if (!node || !node[key]) return def; try { return node[key].as<int>(); } catch (...) { return def; } }
static int ST_YIntAny(const YAML::Node& node, std::initializer_list<const char*> keys, int def) { for (const char* k : keys) { int old = def; int v = ST_YInt(node, k, old); if (v != old || (node && node[k])) return v; } return def; }
static int ST_YSeqInt(const YAML::Node& node, const char* key, size_t idx, int def) { if (!node || !node[key] || !node[key].IsSequence() || node[key].size() <= idx) return def; try { return node[key][idx].as<int>(); } catch (...) { return def; } }

