// ---------------------------------------------------------------------------
// Beta97 Battle Pass / 极速通行证动态版
// 配置: .\24251\SpeedPass.yml。此处不再回放 raw_hex 死包。
// ---------------------------------------------------------------------------

struct SPRewardItemCfg { int ItemID = 0; int ItemNum = 1; int AvailPeriod = 0; int ItemType = 0; int ShowPriority = 0; };
struct SPRewardLevelCfg { int Level = 0; int SpecialFlag = 0; std::vector<SPRewardItemCfg> Free; std::vector<SPRewardItemCfg> Premium; std::vector<SPRewardItemCfg> Collection; };
struct SPPassTierCfg { std::string Tier; int PassType = 0; bool DefaultUnlocked = false; int NeedSpeedCoinCost = 0; int NewSpeedCoinCost = 0; int OldSpeedCoinCost = 0; int UserIncLevel = 0; int IncLevel = 0; std::vector<SPRewardItemCfg> ShowUnlockAward; };
struct SPChildTaskCfg { int TaskID = 0; int TargetCount = 0; int ExecutePeriod = -1; int ShExecuteNum = 0; std::string TargetType; };
struct SPTaskCfg { int TaskID = 0; int TabType = 1; int PassTaskType = 0; int TargetCount = 0; int Exp = 0; int ShowPriority = 0; int OpenDate = 0; int CloseDate = 0; int ExecutePeriod = -1; int ShExecuteNum = 0; int PassTaskNum = 0; int PassTaskMaxLevel = 0; int PassTaskStatus = 0; std::string TargetType; std::vector<SPChildTaskCfg> ChildTasks; };
struct SPRuntimeCfg
{
	bool Loaded = false; bool Enabled = false; UINT ActivityID = 0; int SeasonID = 0;
	int BeginTime = 0; int EndTime = 0; int MaxLevel = 0; int DefaultLevel = 0; int DefaultExp = 0; int DefaultNeedExp = 0;
	int ShowItemID = 0; int ExchangeItemID = 0; int IntervalTimer = 0; int WeekTaskLimit = 0;
	int ShowPassAwardMaxCount = 0; int FreeAwardMaxNum = 0; int AwardMaxNum = 0; int BuyLevelSpeedCoinCost = 0;
	bool PurchaseEnabled = false;
	SPRewardItemCfg EntryAward;
	std::vector<int> LevelNeedExp; std::vector<SPPassTierCfg> Passes; std::vector<SPRewardLevelCfg> Rewards; std::vector<SPTaskCfg> Tasks;
};
struct SPGrantedItem { SPRewardItemCfg Item; int Level = 0; int PassType = 0; std::string Tier; };

static int SP_YInt(const YAML::Node& node, const char* key, int def) { try { if (node && key && node[key]) return node[key].as<int>(); } catch (const std::exception&) {} return def; }
static bool SP_YBool(const YAML::Node& node, const char* key, bool def) { bool out = def; try { if (node && key && node[key] && QQS_YamlTryBoolNoThrow(node[key], out)) return out; } catch (const std::exception&) {} return def; }
static std::string SP_YString(const YAML::Node& node, const char* key, const std::string& def) { try { if (node && key && node[key]) return node[key].as<std::string>(); } catch (const std::exception&) {} return def; }
static YAML::Node SP_LoadYamlCfg()
{
	try { return YAML::LoadFile(".\\24251\\SpeedPass.yml"); }
	catch (const std::exception& e) { QQS_DebugPrintf10001("[SpeedPass] load .\\24251\\SpeedPass.yml failed: %s\n", e.what()); }
	return YAML::Node();
}
static bool SP_HasScalars(const YAML::Node& node, std::initializer_list<const char*> keys)
{
	if (!node || !node.IsMap()) return false;
	for (const char* key : keys) if (!key || !node[key] || !node[key].IsScalar()) return false;
	return true;
}
static void SP_ParseRewardItems(const YAML::Node& rows, std::vector<SPRewardItemCfg>& out)
{
	if (!rows || !rows.IsSequence()) return;
	for (const auto& row : rows)
	{
		SPRewardItemCfg item; item.ItemID = SP_YInt(row, "item_id", 0); item.ItemNum = SP_YInt(row, "item_num", 1);
		item.AvailPeriod = SP_YInt(row, "avail_period", 0); item.ItemType = SP_YInt(row, "item_type", 0); item.ShowPriority = SP_YInt(row, "show_priority", 0);
		if (item.ItemID > 0 && item.ItemNum > 0) out.push_back(item);
	}
}
static void SP_ParseChildTasks(const YAML::Node& rows, std::vector<SPChildTaskCfg>& out)
{
	if (!rows || !rows.IsSequence()) return;
	for (const auto& row : rows)
	{
		SPChildTaskCfg child;
		child.TaskID = SP_YInt(row, "task_id", 0);
		child.TargetType = SP_YString(row, "target_type", "");
		child.TargetCount = SP_YInt(row, "target_count", 0);
		child.ExecutePeriod = SP_YInt(row, "execute_period", -1);
		child.ShExecuteNum = SP_YInt(row, "sh_execute_num", 0);
		if (child.TaskID > 0) out.push_back(child);
	}
}
static void SP_LoadTier(const YAML::Node& passes, const char* key, int passType, bool defUnlocked, std::vector<SPPassTierCfg>& out)
{
	SPPassTierCfg tier; tier.Tier = key ? key : "free"; tier.PassType = passType; tier.DefaultUnlocked = defUnlocked;
	YAML::Node node = (passes && key) ? passes[key] : YAML::Node();
	if (node)
	{
		tier.DefaultUnlocked = SP_YBool(node, "default_unlocked", defUnlocked);
		tier.NeedSpeedCoinCost = SP_YInt(node, "need_speed_coin_cost", 0); tier.NewSpeedCoinCost = tier.NeedSpeedCoinCost;
		tier.OldSpeedCoinCost = SP_YInt(node, "old_speed_coin_cost", 0); tier.IncLevel = SP_YInt(node, "inc_level", 0); tier.UserIncLevel = tier.IncLevel;
		SP_ParseRewardItems(node["show_unlock_awards"], tier.ShowUnlockAward);
	}
	out.push_back(tier);
}
static SPRuntimeCfg SP_LoadRuntimeCfg()
{
	SPRuntimeCfg cfg;
	YAML::Node y = SP_LoadYamlCfg();
	if (!y) return cfg;

	YAML::Node act = y["activity"];
	YAML::Node purchase = y["purchase"];
	YAML::Node entryAward = y["entry_award"];
	YAML::Node passes = y["passes"];
	YAML::Node premium = passes ? passes["premium"] : YAML::Node();
	YAML::Node collection = passes ? passes["collection"] : YAML::Node();
	YAML::Node rewards = y["rewards"];
	YAML::Node tasks = y["tasks"];
	const bool schemaOK =
		SP_HasScalars(y, { "enabled" }) &&
		SP_HasScalars(act, {
			"activity_id", "season_id", "begin_time", "end_time", "max_level",
			"default_level", "default_exp", "need_exp", "show_item_id",
			"exchange_item_id", "interval_timer", "week_task_limit",
			"show_pass_award_max_count", "free_award_max_num", "award_max_num",
			"buy_level_speed_coin_cost" }) &&
		SP_HasScalars(purchase, { "enabled" }) &&
		SP_HasScalars(entryAward, { "item_id", "item_num", "avail_period", "item_type" }) &&
		SP_HasScalars(premium, { "default_unlocked", "need_speed_coin_cost", "old_speed_coin_cost", "inc_level" }) &&
		SP_HasScalars(collection, { "default_unlocked", "need_speed_coin_cost", "old_speed_coin_cost", "inc_level" }) &&
		premium["show_unlock_awards"] && premium["show_unlock_awards"].IsSequence() &&
		collection["show_unlock_awards"] && collection["show_unlock_awards"].IsSequence() &&
		rewards && rewards.IsSequence() && tasks && tasks.IsSequence();
	if (!schemaOK)
	{
		QQS_DebugPrintf10001("[SpeedPass] invalid .\\24251\\SpeedPass.yml: missing or invalid required field\n");
		return cfg;
	}

	cfg.Enabled = SP_YBool(y, "enabled", false);
	cfg.ActivityID = static_cast<UINT>(SP_YInt(act, "activity_id", 0));
	cfg.SeasonID = SP_YInt(act, "season_id", 0);
	cfg.BeginTime = SP_YInt(act, "begin_time", 0);
	cfg.EndTime = SP_YInt(act, "end_time", 0);
	cfg.MaxLevel = SP_YInt(act, "max_level", 0);
	cfg.DefaultLevel = SP_YInt(act, "default_level", 0);
	cfg.DefaultExp = SP_YInt(act, "default_exp", 0);
	cfg.DefaultNeedExp = SP_YInt(act, "need_exp", 0);
	cfg.ShowItemID = SP_YInt(act, "show_item_id", 0);
	cfg.ExchangeItemID = SP_YInt(act, "exchange_item_id", 0);
	cfg.IntervalTimer = SP_YInt(act, "interval_timer", 0);
	cfg.WeekTaskLimit = SP_YInt(act, "week_task_limit", 0);
	cfg.ShowPassAwardMaxCount = SP_YInt(act, "show_pass_award_max_count", 0);
	cfg.FreeAwardMaxNum = SP_YInt(act, "free_award_max_num", 0);
	cfg.AwardMaxNum = SP_YInt(act, "award_max_num", 0);
	cfg.BuyLevelSpeedCoinCost = SP_YInt(act, "buy_level_speed_coin_cost", 0);
	cfg.PurchaseEnabled = SP_YBool(purchase, "enabled", false);
	cfg.EntryAward.ItemID = SP_YInt(entryAward, "item_id", 0);
	cfg.EntryAward.ItemNum = SP_YInt(entryAward, "item_num", 0);
	cfg.EntryAward.AvailPeriod = SP_YInt(entryAward, "avail_period", 0);
	cfg.EntryAward.ItemType = SP_YInt(entryAward, "item_type", 0);

	YAML::Node levels = y["levels"];
	if (levels && levels["per_level"] && levels["per_level"].IsSequence())
	{
		cfg.LevelNeedExp.assign(static_cast<size_t>(cfg.MaxLevel) + 1, cfg.DefaultNeedExp);
		for (const auto& row : levels["per_level"])
		{
			int level = SP_YInt(row, "level", 0);
			if (level >= 1 && level <= cfg.MaxLevel)
				cfg.LevelNeedExp[static_cast<size_t>(level)] = std::max(0, SP_YInt(row, "need_exp", cfg.DefaultNeedExp));
		}
	}

	SP_LoadTier(passes, "free", 1, true, cfg.Passes);
	SP_LoadTier(passes, "premium", 2, false, cfg.Passes);
	SP_LoadTier(passes, "collection", 3, false, cfg.Passes);

	for (const auto& row : rewards)
	{
		SPRewardLevelCfg reward;
		reward.Level = SP_YInt(row, "level", 0);
		reward.SpecialFlag = SP_YInt(row, "special_flag", 0);
		SP_ParseRewardItems(row["free"], reward.Free);
		SP_ParseRewardItems(row["premium"], reward.Premium);
		SP_ParseRewardItems(row["collection"], reward.Collection);
		if (reward.Level > 0) cfg.Rewards.push_back(reward);
	}
	for (const auto& row : tasks)
	{
		SPTaskCfg task;
		task.TaskID = SP_YInt(row, "task_id", 0); task.TabType = SP_YInt(row, "tab_type", 1); task.PassTaskType = SP_YInt(row, "pass_task_type", 0);
		task.TargetType = SP_YString(row, "target_type", ""); task.TargetCount = SP_YInt(row, "target_count", 0);
		task.Exp = SP_YInt(row, "exp", -1); task.ShowPriority = SP_YInt(row, "show_priority", 0); task.OpenDate = SP_YInt(row, "open_date", 0);
		task.CloseDate = SP_YInt(row, "close_date", 0); task.ExecutePeriod = SP_YInt(row, "execute_period", -1);
		task.ShExecuteNum = SP_YInt(row, "sh_execute_num", 0); task.PassTaskNum = SP_YInt(row, "pass_task_num", 0); task.PassTaskMaxLevel = SP_YInt(row, "pass_task_max_level", 0);
		task.PassTaskStatus = SP_YInt(row, "pass_task_status", 0); SP_ParseChildTasks(row["child_tasks"], task.ChildTasks);
		if (task.TaskID > 0) cfg.Tasks.push_back(task);
	}

	bool tasksOK = !cfg.Tasks.empty();
	for (const auto& task : cfg.Tasks)
	{
		tasksOK =
			tasksOK &&
			task.TaskID > 0 &&
			task.TargetCount > 0 &&
			task.Exp >= 0 &&
			(task.ExecutePeriod == 0 || task.ExecutePeriod == 2) &&
			(task.ShExecuteNum == -1 || task.ShExecuteNum > 0);
		for (const auto& child : task.ChildTasks)
		{
			tasksOK =
				tasksOK &&
				child.TaskID > 0 &&
				child.TargetCount > 0 &&
				child.ExecutePeriod == task.ExecutePeriod &&
				(child.ShExecuteNum == -1 || child.ShExecuteNum > 0);
		}
	}

	const auto task5700 = std::find_if(
		cfg.Tasks.begin(),
		cfg.Tasks.end(),
		[](const SPTaskCfg& task) { return task.TaskID == 5700; });
	const auto task5702 = std::find_if(
		cfg.Tasks.begin(),
		cfg.Tasks.end(),
		[](const SPTaskCfg& task) { return task.TaskID == 5702; });
	const auto task5703 = std::find_if(
		cfg.Tasks.begin(),
		cfg.Tasks.end(),
		[](const SPTaskCfg& task) { return task.TaskID == 5703; });
	bool officialCoreTaskChainOK =
		task5700 != cfg.Tasks.end() &&
		task5700->TargetType == "race_or_dance_finish" &&
		task5700->TargetCount == 1 &&
		task5700->ExecutePeriod == 2 &&
		task5700->ShExecuteNum == -1 &&
		task5702 != cfg.Tasks.end() &&
		task5702->TargetType.empty() &&
		task5702->TargetCount == 1 &&
		task5702->ExecutePeriod == 2 &&
		task5702->ShExecuteNum == 1 &&
		task5703 != cfg.Tasks.end() &&
		task5703->TargetType.empty() &&
		task5703->TargetCount == 3 &&
		task5703->ExecutePeriod == 2 &&
		task5703->ShExecuteNum == 1;
	if (officialCoreTaskChainOK)
	{
		const auto child5666 = std::find_if(
			task5702->ChildTasks.begin(),
			task5702->ChildTasks.end(),
			[](const SPChildTaskCfg& child) { return child.TaskID == 5666; });
		const auto child5667 = std::find_if(
			task5702->ChildTasks.begin(),
			task5702->ChildTasks.end(),
			[](const SPChildTaskCfg& child) { return child.TaskID == 5667; });
		officialCoreTaskChainOK =
			child5666 != task5702->ChildTasks.end() &&
			child5666->TargetType == "race_finish" &&
			child5666->TargetCount == 1 &&
			child5666->ExecutePeriod == 2 &&
			child5666->ShExecuteNum == -1 &&
			child5667 != task5702->ChildTasks.end() &&
			child5667->TargetType == "dance_perfect" &&
			child5667->TargetCount == 5 &&
			child5667->ExecutePeriod == 2 &&
			child5667->ShExecuteNum == -1;
	}
	if (officialCoreTaskChainOK)
	{
		const auto child5668 = std::find_if(
			task5703->ChildTasks.begin(),
			task5703->ChildTasks.end(),
			[](const SPChildTaskCfg& child) { return child.TaskID == 5668; });
		const auto child5669 = std::find_if(
			task5703->ChildTasks.begin(),
			task5703->ChildTasks.end(),
			[](const SPChildTaskCfg& child) { return child.TaskID == 5669; });
		officialCoreTaskChainOK =
			child5668 != task5703->ChildTasks.end() &&
			child5668->TargetType == "race_finish" &&
			child5668->TargetCount == 1 &&
			child5668->ExecutePeriod == 2 &&
			child5668->ShExecuteNum == -1 &&
			child5669 != task5703->ChildTasks.end() &&
			child5669->TargetType == "dance_perfect" &&
			child5669->TargetCount == 5 &&
			child5669->ExecutePeriod == 2 &&
			child5669->ShExecuteNum == -1;
	}

	const auto taskMappingOK =
		[&cfg](
			int taskID,
			const char* targetType,
			int targetCount,
			int executePeriod,
			int shExecuteNum) {
			const auto found = std::find_if(
				cfg.Tasks.begin(),
				cfg.Tasks.end(),
				[taskID](const SPTaskCfg& task) {
					return task.TaskID == taskID;
				});
			return
				found != cfg.Tasks.end() &&
				found->TargetType == targetType &&
				found->TargetCount == targetCount &&
				found->ExecutePeriod == executePeriod &&
				found->ShExecuteNum == shExecuteNum;
		};
	const auto childMappingOK =
		[&cfg](
			int parentTaskID,
			int childTaskID,
			const char* targetType,
			int targetCount) {
			const auto parent = std::find_if(
				cfg.Tasks.begin(),
				cfg.Tasks.end(),
				[parentTaskID](const SPTaskCfg& task) {
					return task.TaskID == parentTaskID;
				});
			if (parent == cfg.Tasks.end())
				return false;
			const auto child = std::find_if(
				parent->ChildTasks.begin(),
				parent->ChildTasks.end(),
				[childTaskID](const SPChildTaskCfg& task) {
					return task.TaskID == childTaskID;
				});
			return
				child != parent->ChildTasks.end() &&
				child->TargetType == targetType &&
				child->TargetCount == targetCount &&
				child->ExecutePeriod == parent->ExecutePeriod &&
				child->ShExecuteNum == -1;
		};

	bool supportedTaskMappingsOK =
		taskMappingOK(5704, "", 1, 2, 1) &&
		taskMappingOK(5705, "", 3, 2, 1) &&
		taskMappingOK(5706, "", 10, 0, 1) &&
		taskMappingOK(5707, "", 30, 0, 1) &&
		taskMappingOK(5708, "", 5, 0, 1) &&
		taskMappingOK(5709, "", 25, 0, 1) &&
		taskMappingOK(5710, "", 50, 0, 1) &&
		taskMappingOK(5674, "kart_refit", 5, 2, 1) &&
		taskMappingOK(5675, "kart_refit", 20, 2, 1) &&
		taskMappingOK(5679, "login_day", 5, 0, 1) &&
		taskMappingOK(5680, "login_day", 10, 0, 1) &&
		taskMappingOK(5681, "login_day", 15, 0, 1) &&
		taskMappingOK(5688, "race_champion", 5, 0, 1) &&
		taskMappingOK(5689, "race_champion", 15, 0, 1) &&
		taskMappingOK(5690, "race_champion", 30, 0, 1) &&
		taskMappingOK(5697, "gem_synthesis", 10, 0, 1) &&
		taskMappingOK(5698, "kart_refit", 300, 0, 1) &&
		taskMappingOK(5699, "kart_refit", 600, 0, 1) &&
		taskMappingOK(5701, "race_or_dance_finish", 1, 0, 16959) &&
		childMappingOK(5704, 5670, "ranked_finish", 1) &&
		childMappingOK(5704, 5671, "border_finish", 1) &&
		childMappingOK(5705, 5672, "ranked_finish", 1) &&
		childMappingOK(5705, 5673, "border_finish", 1) &&
		childMappingOK(5706, 5682, "track_workshop_finish", 1) &&
		childMappingOK(5707, 5685, "track_workshop_finish", 1) &&
		childMappingOK(5708, 5691, "ranked_win", 1) &&
		childMappingOK(5708, 5692, "border_top3", 1) &&
		childMappingOK(5709, 5693, "ranked_win", 1) &&
		childMappingOK(5709, 5694, "border_top3", 1) &&
		childMappingOK(5710, 5695, "ranked_win", 1) &&
		childMappingOK(5710, 5696, "border_top3", 1);
	const auto sprintTask = std::find_if(
		cfg.Tasks.begin(),
		cfg.Tasks.end(),
		[](const SPTaskCfg& task) { return task.TaskID == 5701; });
	supportedTaskMappingsOK =
		supportedTaskMappingsOK &&
		sprintTask != cfg.Tasks.end() &&
		sprintTask->PassTaskType == 1 &&
		sprintTask->PassTaskMaxLevel == 150 &&
		sprintTask->OpenDate == 20260821 &&
		sprintTask->CloseDate == 20260827;

	const SPPassTierCfg& premiumCfg = cfg.Passes[1];
	const SPPassTierCfg& collectionCfg = cfg.Passes[2];
	const bool valuesOK =
		cfg.ActivityID > 0 && cfg.SeasonID > 0 &&
		cfg.BeginTime > 0 && cfg.EndTime > cfg.BeginTime &&
		cfg.MaxLevel > 0 && cfg.DefaultLevel >= 1 && cfg.DefaultLevel <= cfg.MaxLevel &&
		cfg.DefaultExp >= 0 && cfg.DefaultNeedExp > 0 &&
		cfg.ShowItemID > 0 && cfg.ExchangeItemID > 0 && cfg.IntervalTimer > 0 &&
		cfg.WeekTaskLimit > 0 && cfg.ShowPassAwardMaxCount > 0 &&
		cfg.FreeAwardMaxNum > 0 && cfg.FreeAwardMaxNum <= cfg.AwardMaxNum &&
		cfg.AwardMaxNum <= cfg.MaxLevel && cfg.BuyLevelSpeedCoinCost > 0 &&
		cfg.EntryAward.ItemID > 0 && cfg.EntryAward.ItemNum > 0 &&
		premiumCfg.NeedSpeedCoinCost > 0 && premiumCfg.OldSpeedCoinCost >= 0 && premiumCfg.IncLevel >= 0 &&
		collectionCfg.NeedSpeedCoinCost > 0 && collectionCfg.OldSpeedCoinCost >= 0 && collectionCfg.IncLevel >= 0 &&
		!cfg.Rewards.empty() && tasksOK && officialCoreTaskChainOK &&
		supportedTaskMappingsOK;
	if (!valuesOK)
	{
		QQS_DebugPrintf10001("[SpeedPass] invalid .\\24251\\SpeedPass.yml: value out of range\n");
		return SPRuntimeCfg();
	}
	cfg.Loaded = true;
	return cfg;
}
static int SP_SeasonWeekKey(const SPRuntimeCfg& cfg)
{
	const time_t now = time(nullptr);
	if (cfg.BeginTime <= 0 || now < static_cast<time_t>(cfg.BeginTime))
		return -1;
	return static_cast<int>(
		(now - static_cast<time_t>(cfg.BeginTime)) / (86400 * 7));
}
static std::string SP_PeriodKey(const SPRuntimeCfg& cfg, int executePeriod)
{
	if (executePeriod == 2)
		return std::string("W") + std::to_string(SP_SeasonWeekKey(cfg));
	return "S0";
}
static bool SP_IsActive(const SPRuntimeCfg& cfg)
{
	const time_t now = time(nullptr);
	return cfg.Loaded &&
		cfg.Enabled &&
		now >= static_cast<time_t>(cfg.BeginTime) &&
		now <= static_cast<time_t>(cfg.EndTime);
}
static int SP_GetNeedExp(const SPRuntimeCfg& cfg, int level) { if (level >= cfg.MaxLevel) return 0; if (level >= 1 && level < (int)cfg.LevelNeedExp.size()) return std::max(0, cfg.LevelNeedExp[(size_t)level]); return std::max(0, cfg.DefaultNeedExp); }
static int SP_DisplayWeekTaskScore(const SPRuntimeCfg& cfg, const SpeedPassStateRow& st)
{
	int score = st.WeekTaskCurScore < 0 ? 0 : st.WeekTaskCurScore;
	if (cfg.WeekTaskLimit > 0 && score > cfg.WeekTaskLimit) score = cfg.WeekTaskLimit;
	return score;
}
static SpeedPassStateRow SP_LoadState(UINT uin, const SPRuntimeCfg& cfg)
{
	SpeedPassStateRow st; st.Uin = uin; st.ActivityId = cfg.ActivityID; st.CurLevel = cfg.DefaultLevel; st.CurExp = cfg.DefaultExp; PlayerDB_SPLoadState(uin, cfg.ActivityID, st);
	if (st.CurLevel < 1) st.CurLevel = 1; if (st.CurLevel > cfg.MaxLevel) st.CurLevel = cfg.MaxLevel; if (st.CurExp < 0) st.CurExp = 0;
	const int week = SP_SeasonWeekKey(cfg); bool dirty = false;
	if (st.LastWeeklyReset != week) { st.LastWeeklyReset = week; st.WeekTaskCurScore = 0; dirty = true; }
	if (st.WeekTaskCurScore < 0) { st.WeekTaskCurScore = 0; dirty = true; }
	if (st.WeekTaskCurScore > cfg.WeekTaskLimit) { st.WeekTaskCurScore = cfg.WeekTaskLimit; dirty = true; }
	if (dirty) PlayerDB_SPSaveState(uin, cfg.ActivityID, st); return st;
}
static const SPRewardLevelCfg* SP_FindRewardLevel(const SPRuntimeCfg& cfg, int level) { for (const auto& row : cfg.Rewards) if (row.Level == level) return &row; return nullptr; }
static const std::vector<SPRewardItemCfg>& SP_TierRewards(const SPRewardLevelCfg& row, const std::string& tier) { if (tier == "premium") return row.Premium; if (tier == "collection") return row.Collection; return row.Free; }
static bool SP_IsTierUnlocked(const SpeedPassStateRow& st, const SPPassTierCfg& tier) { if (tier.Tier == "free") return true; if (tier.Tier == "premium") return tier.DefaultUnlocked || st.PremiumUnlocked != 0; if (tier.Tier == "collection") return tier.DefaultUnlocked || st.CollectionUnlocked != 0; return tier.DefaultUnlocked; }
static bool SP_HasPaidPass(const SPRuntimeCfg& cfg, const SpeedPassStateRow& state)
{
	for (const auto& tier : cfg.Passes)
	{
		if (tier.PassType > 1 && SP_IsTierUnlocked(state, tier))
			return true;
	}
	return false;
}
static int SP_RewardStatus(UINT uin, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st, const SPPassTierCfg& tier, int level, bool hasReward)
{
	if (!hasReward || level > st.CurLevel) return 0;
	if (!SP_IsTierUnlocked(st, tier)) return 3;
	return PlayerDB_SPIsClaimed(uin, cfg.ActivityID, tier.Tier, level) ? 2 : 1;
}
static void SP_WriteRewardItem(BYTE*& p, const SPRewardItemCfg& item, bool includeShowPriority = false)
{
	// 官方 Battle_Pass_AwardInfo itemInfos 字段顺序为：m_iAvailPeriod / m_ushItemType / m_iItemNum / m_iItemID。
	// 这里默认不写 m_uiShowPriority，避免额外 key 进入 QuickRPC 字典后客户端奖励格解析错位。
	CT_WriteTextNumber(p, "m_iAvailPeriod", item.AvailPeriod);
	CT_WriteTextNumber(p, "m_ushItemType", item.ItemType);
	CT_WriteTextNumber(p, "m_iItemNum", item.ItemNum);
	CT_WriteTextNumber(p, "m_iItemID", item.ItemID);
	if (includeShowPriority && item.ShowPriority > 0) CT_WriteTextNumber(p, "m_usShowPriority", item.ShowPriority);
}
static void SP_WriteRewardItemArray(BYTE*& p, const char* key, const std::vector<SPRewardItemCfg>& items)
{
	CT_WriteKey(p, key); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	for (size_t i = 0; i < items.size(); ++i) CT_WriteIndexedObject(p, (int)i + 1, [&](BYTE*& itemP) { SP_WriteRewardItem(itemP, items[i]); });
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WriteUnlockRewardItem(BYTE*& p, const SPRewardItemCfg& item)
{
	CT_WriteTextNumber(p, "m_iAvailPeriod", item.AvailPeriod);
	CT_WriteTextNumber(p, "m_ushItemType", item.ItemType);
	CT_WriteTextNumber(p, "m_iItemID", item.ItemID);
	CT_WriteTextNumber(p, "m_iItemNum", item.ItemNum);
}
static void SP_WriteUnlockRewardItemArray(BYTE*& p, const char* key, const std::vector<SPRewardItemCfg>& items)
{
	CT_WriteKey(p, key); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	for (size_t i = 0; i < items.size(); ++i) CT_WriteIndexedObject(p, (int)i + 1, [&](BYTE*& itemP) { SP_WriteUnlockRewardItem(itemP, items[i]); });
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WriteBaseCfg(BYTE*& p, const SPRuntimeCfg& cfg)
{
	CT_WriteKey(p, "baseCfg"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	CT_WriteTextNumber(p, "showItemId", cfg.ShowItemID); CT_WriteTextNumber(p, "ShowPassAwardMaxCount", cfg.ShowPassAwardMaxCount); CT_WriteTextNumber(p, "endTime", cfg.EndTime); CT_WriteTextNumber(p, "IntervalTimer", cfg.IntervalTimer);
	CT_WriteTextNumber(p, "WeekTaskLimit", cfg.WeekTaskLimit); CT_WriteTextNumber(p, "seasonid", cfg.SeasonID); CT_WriteTextNumber(p, "FreeAwardMaxNum", cfg.FreeAwardMaxNum); CT_WriteTextNumber(p, "AwardMaxNum", cfg.AwardMaxNum);
	CT_WriteTextNumber(p, "BuyLevelSpeedCoinCost", cfg.BuyLevelSpeedCoinCost); CT_WriteTextNumber(p, "beginTime", cfg.BeginTime);
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WritePlayerInfo(BYTE*& p, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st, UINT uin)
{
	CT_WriteKey(p, "PlayerInfo"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	CT_WriteTextNumber(p, "ExchangeItemID", cfg.ExchangeItemID); CT_WriteTextNumber(p, "CurExp", st.CurExp); CT_WriteTextNumber(p, "WeekTaskCurScore", SP_DisplayWeekTaskScore(cfg, st)); CT_WriteTextNumber(p, "CurLevel", st.CurLevel); CT_WriteTextNumber(p, "NeedExp", SP_GetNeedExp(cfg, st.CurLevel)); CT_WriteTextNumber(p, "ExchangeItemNum", PlayerDB_GetItemNum(uin, cfg.ExchangeItemID));
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WritePlayerInfoSimple(BYTE*& p, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st)
{
	CT_WriteKey(p, "PlayerInfo"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	CT_WriteTextNumber(p, "CurLevel", st.CurLevel); CT_WriteTextNumber(p, "CurExp", st.CurExp); CT_WriteTextNumber(p, "NeedExp", SP_GetNeedExp(cfg, st.CurLevel));
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WritePassInfo(BYTE*& p, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st)
{
	CT_WriteKey(p, "PassInfo"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	for (size_t i = 0; i < cfg.Passes.size(); ++i)
	{
		const auto& pass = cfg.Passes[i];
		CT_WriteIndexedObject(p, (int)i + 1, [&](BYTE*& passP) {
			CT_WriteTextNumber(passP, "pass_type", pass.PassType);
			if (pass.ShowUnlockAward.empty()) CT_WriteEmptyTable(passP, "ShowUnlockAward"); else SP_WriteUnlockRewardItemArray(passP, "ShowUnlockAward", pass.ShowUnlockAward);
			CT_WriteTextNumber(passP, "NeedSpeedCoinCost", pass.NeedSpeedCoinCost);
			CT_WriteTextNumber(passP, "NewSpeedCoinCost", pass.NewSpeedCoinCost);
			CT_WriteTextNumber(passP, "OldSpeedCoinCost", pass.OldSpeedCoinCost);
			CT_WriteTextNumber(passP, "UserIncLevel", pass.UserIncLevel);
			CT_WriteTextNumber(passP, "unlockFlag", SP_IsTierUnlocked(st, pass) ? 1 : 0);
			CT_WriteTextNumber(passP, "IncLevel", pass.IncLevel);
		});
	}
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WriteOneAwardLevel(BYTE*& p, UINT uin, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st, int level)
{
	const SPRewardLevelCfg* row = SP_FindRewardLevel(cfg, level); static const std::vector<SPRewardItemCfg> empty;
	CT_WriteTextNumber(p, "pass_level", level); CT_WriteTextNumber(p, "specialFlag", row ? row->SpecialFlag : 0); CT_WriteKey(p, "pass_award"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	for (size_t i = 0; i < cfg.Passes.size(); ++i) { const auto& tier = cfg.Passes[i]; const auto& items = row ? SP_TierRewards(*row, tier.Tier) : empty; int status = SP_RewardStatus(uin, cfg, st, tier, level, !items.empty()); CT_WriteIndexedObject(p, (int)i + 1, [&](BYTE*& passP) { CT_WriteTextNumber(passP, "Status", status); SP_WriteRewardItemArray(passP, "itemInfos", items); CT_WriteTextNumber(passP, "pass_type", tier.PassType); }); }
	CT_WriteLenValueEnd(len, start, p);
}
static void SP_WriteAwardInfoRows(BYTE*& p, UINT uin, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st, int startLevel, int endLevel)
{
	if (startLevel < 1) startLevel = 1; if (endLevel < startLevel) endLevel = startLevel; if (endLevel > cfg.MaxLevel) endLevel = cfg.MaxLevel;
	int idx = 1;
	for (int level = startLevel; level <= endLevel; ++level) CT_WriteIndexedObject(p, idx++, [&](BYTE*& levelP) { SP_WriteOneAwardLevel(levelP, uin, cfg, st, level); });
}
static void SP_WriteEntryAwardInfo(BYTE*& p, UINT uin, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st)
{
	SPPassTierCfg freeTier; freeTier.Tier = "free"; freeTier.PassType = 1; freeTier.DefaultUnlocked = true;
	bool hasReward = false;
	const SPRewardLevelCfg* row = SP_FindRewardLevel(cfg, st.CurLevel);
	if (row && !row->Free.empty()) hasReward = true;
	CT_WriteKey(p, "AwardInfo"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	CT_WriteTextNumber(p, "m_iAvailPeriod", cfg.EntryAward.AvailPeriod);
	CT_WriteTextNumber(p, "m_ushItemType", cfg.EntryAward.ItemType);
	CT_WriteTextNumber(p, "m_iItemID", cfg.EntryAward.ItemID);
	CT_WriteTextNumber(p, "m_iItemNum", cfg.EntryAward.ItemNum);
	CT_WriteLenValueEnd(len, start, p);
	CT_WriteTextNumber(p, "AwardStatus", SP_RewardStatus(uin, cfg, st, freeTier, st.CurLevel, hasReward));
}
static SpeedPassTaskStateRow SP_LoadTaskState(
	UINT uin,
	const SPRuntimeCfg& cfg,
	int taskID,
	int executePeriod)
{
	SpeedPassTaskStateRow state;
	state.Uin = uin;
	state.ActivityId = cfg.ActivityID;
	state.TaskId = taskID;
	state.PeriodKey = SP_PeriodKey(cfg, executePeriod);
	PlayerDB_SPLoadTaskState(
		uin,
		cfg.ActivityID,
		taskID,
		state.PeriodKey,
		state);
	if (state.Progress < 0) state.Progress = 0;
	if (state.AwardCount < 0) state.AwardCount = 0;
	return state;
}

static SpeedPassTaskStateRow SP_LoadTaskState(
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SPTaskCfg& task)
{
	return SP_LoadTaskState(uin, cfg, task.TaskID, task.ExecutePeriod);
}

static void SP_WriteTaskTable(
	BYTE*& p,
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& st)
{
	CT_WriteKey(p, "taskTable"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	for (size_t i = 0; i < cfg.Tasks.size(); ++i)
	{
		const auto& task = cfg.Tasks[i]; SpeedPassTaskStateRow ts = SP_LoadTaskState(uin, cfg, task);
		const int passTaskStatus =
			task.PassTaskType == 1
			? (SP_HasPaidPass(cfg, st) ? 1 : 0)
			: task.PassTaskStatus;
		CT_WriteIndexedObject(p, (int)i + 1, [&](BYTE*& taskP) {
			CT_WriteTextNumber(taskP, "m_ucTaskID", task.TaskID);
			CT_WriteTextNumber(taskP, "m_uiAwardMoveNums", task.Exp);
			CT_WriteTextNumber(taskP, "tabType", task.TabType);
			CT_WriteTextNumber(taskP, "closeDate", task.CloseDate);
			CT_WriteTextNumber(taskP, "m_usShowPriority", task.ShowPriority);
			if (task.PassTaskType != 1) CT_WriteTextNumber(taskP, "m_uiProcessRate", std::min(ts.Progress, task.TargetCount));
			CT_WriteTextNumber(taskP, "pass_task_type", task.PassTaskType);
			CT_WriteTextNumber(taskP, "m_uiTaskFinishNums", task.TargetCount);
			CT_WriteTextNumber(taskP, "openDate", task.OpenDate);
			CT_WriteTextNumber(taskP, "ExecutePeriod", task.ExecutePeriod);
			if (!task.ChildTasks.empty())
			{
				CT_WriteKey(taskP, "m_auiChildTask"); BYTE* childLen = CT_WriteLenValueStart(taskP); BYTE* childStart = taskP;
				for (size_t ci = 0; ci < task.ChildTasks.size(); ++ci)
				{
					const auto& child = task.ChildTasks[ci];
					const SpeedPassTaskStateRow childState = SP_LoadTaskState(
						uin,
						cfg,
						child.TaskID,
						child.ExecutePeriod);
					CT_WriteIndexedObject(taskP, (int)ci + 1, [&](BYTE*& childP) {
						CT_WriteTextNumber(
							childP,
							"m_uiProcessRate",
							std::min(childState.Progress, child.TargetCount));
						CT_WriteTextNumber(childP, "m_ucTaskID", child.TaskID);
						CT_WriteTextNumber(childP, "m_uiTaskFinishNums", child.TargetCount);
						CT_WriteTextNumber(childP, "ExecutePeriod", child.ExecutePeriod);
						CT_WriteTextNumber(
							childP,
							"m_uiAlreadyAwardNums",
							childState.AwardCount);
						CT_WriteTextNumber(childP, "m_shExecuteNum", child.ShExecuteNum);
					});
				}
				CT_WriteLenValueEnd(childLen, childStart, taskP);
			}
			if (task.PassTaskType != 0 || task.PassTaskNum != 0) CT_WriteTextNumber(taskP, "pass_task_num", task.PassTaskNum);
			if (task.PassTaskMaxLevel > 0) CT_WriteTextNumber(taskP, "PassTaskMaxLevel", task.PassTaskMaxLevel);
			if (task.PassTaskType != 1) CT_WriteTextNumber(taskP, "m_uiAlreadyAwardNums", ts.AwardCount);
			CT_WriteTextNumber(taskP, "m_shExecuteNum", task.ShExecuteNum);
			if (task.PassTaskType != 0 || passTaskStatus != 0) CT_WriteTextNumber(taskP, "pass_task_status", passTaskStatus);
		});
	}
	CT_WriteLenValueEnd(len, start, p);
}
static const SPTaskCfg* SP_FindTaskCfg(const SPRuntimeCfg& cfg, int taskID);
static void SP_WriteTaskInfo(BYTE*& p, UINT uin, const SPRuntimeCfg& cfg, const SpeedPassStateRow& st)
{
	SP_WritePlayerInfoSimple(p, cfg, st); CT_WriteKey(p, "AwardTable"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	int activityNum = 0;
	for (int taskID : { 5676, 5677, 5678 })
	{
		const SPTaskCfg* task = SP_FindTaskCfg(cfg, taskID);
		if (!task) continue;
		const SpeedPassTaskStateRow taskState = SP_LoadTaskState(uin, cfg, *task);
		activityNum = (std::max)(activityNum, (std::min)(taskState.Progress, task->TargetCount));
	}
	CT_WriteTextNumber(p, "activity_num", activityNum); CT_WriteEmptyTable(p, "activity_award"); CT_WriteLenValueEnd(len, start, p); SP_WriteTaskTable(p, uin, cfg, st);
}

struct SPSettlementRecord
{
	int GameBeginLevel = 0;
	int GameBeginExp = 0;
	int AddExp = 0;
	SpeedPassStateRow CurrentState;
};

static std::mutex g_SPSettlementMutex;
static std::unordered_map<UINT, SPSettlementRecord> g_SPPendingSettlements;

static const SPTaskCfg* SP_FindTaskCfg(
	const SPRuntimeCfg& cfg,
	int taskID)
{
	const auto found = std::find_if(
		cfg.Tasks.begin(),
		cfg.Tasks.end(),
		[taskID](const SPTaskCfg& task) {
			return task.TaskID == taskID;
		});
	return found == cfg.Tasks.end() ? nullptr : &*found;
}

static const SPChildTaskCfg* SP_FindChildTaskCfg(
	const SPTaskCfg& parent,
	int taskID)
{
	const auto found = std::find_if(
		parent.ChildTasks.begin(),
		parent.ChildTasks.end(),
		[taskID](const SPChildTaskCfg& task) {
			return task.TaskID == taskID;
		});
	return found == parent.ChildTasks.end() ? nullptr : &*found;
}

static SpeedPassTaskStateRow& SP_GetChangedTaskState(
	UINT uin,
	const SPRuntimeCfg& cfg,
	int taskID,
	int executePeriod,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	const std::string periodKey = SP_PeriodKey(cfg, executePeriod);
	const auto found = std::find_if(
		changedStates.begin(),
		changedStates.end(),
		[taskID, &periodKey](const SpeedPassTaskStateRow& state) {
			return state.TaskId == taskID && state.PeriodKey == periodKey;
		});
	if (found != changedStates.end())
		return *found;

	changedStates.push_back(
		SP_LoadTaskState(uin, cfg, taskID, executePeriod));
	return changedStates.back();
}

struct SPTaskExpGain
{
	int Weekly = 0;
	int Season = 0;

	int Total() const { return Weekly + Season; }
	SPTaskExpGain& operator+=(const SPTaskExpGain& other)
	{
		Weekly += other.Weekly;
		Season += other.Season;
		return *this;
	}
};

static SPTaskExpGain SP_MakeTaskExpGain(const SPTaskCfg& task)
{
	SPTaskExpGain gain;
	if (task.Exp <= 0)
		return gain;
	if (task.ExecutePeriod == 2)
		gain.Weekly = task.Exp;
	else
		gain.Season = task.Exp;
	return gain;
}

static int SP_ApplyTaskExp(
	const SPRuntimeCfg& cfg,
	SpeedPassStateRow& state,
	const SPTaskExpGain& gain)
{
	const int weeklyRemaining =
		(std::max)(0, cfg.WeekTaskLimit - state.WeekTaskCurScore);
	const int appliedWeekly =
		(std::min)((std::max)(0, gain.Weekly), weeklyRemaining);
	const int appliedSeason = (std::max)(0, gain.Season);
	const int appliedTotal = appliedWeekly + appliedSeason;

	state.WeekTaskCurScore += appliedWeekly;
	if (appliedTotal <= 0)
		return 0;
	if (state.CurLevel < 1)
		state.CurLevel = 1;
	if (state.CurLevel >= cfg.MaxLevel)
	{
		state.CurLevel = cfg.MaxLevel;
		state.CurExp = 0;
		return appliedTotal;
	}

	state.CurExp += appliedTotal;
	while (state.CurLevel < cfg.MaxLevel)
	{
		const int need = SP_GetNeedExp(cfg, state.CurLevel);
		if (need <= 0 || state.CurExp < need)
			break;
		state.CurExp -= need;
		++state.CurLevel;
	}
	if (state.CurLevel >= cfg.MaxLevel)
	{
		state.CurLevel = cfg.MaxLevel;
		state.CurExp = 0;
	}
	return appliedTotal;
}

static SPTaskExpGain SP_ApplyRepeatTask(
	UINT uin,
	const SPRuntimeCfg& cfg,
	int taskID,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	const SPTaskCfg* task = SP_FindTaskCfg(cfg, taskID);
	if (!task)
		return {};

	SpeedPassTaskStateRow& state = SP_GetChangedTaskState(
		uin,
		cfg,
		task->TaskID,
		task->ExecutePeriod,
		changedStates);
	state.Progress = task->TargetCount;
	if (state.AwardCount < std::numeric_limits<int>::max())
		++state.AwardCount;
	return SP_MakeTaskExpGain(*task);
}

static SPTaskExpGain SP_ApplyDirectTaskProgress(
	UINT uin,
	const SPRuntimeCfg& cfg,
	int taskID,
	int amount,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	const SPTaskCfg* task = SP_FindTaskCfg(cfg, taskID);
	if (!task || amount <= 0)
		return {};

	SpeedPassTaskStateRow& state = SP_GetChangedTaskState(
		uin,
		cfg,
		task->TaskID,
		task->ExecutePeriod,
		changedStates);
	if (task->ShExecuteNum > 0 &&
		state.AwardCount >= task->ShExecuteNum)
	{
		return {};
	}

	const long long nextProgress =
		static_cast<long long>(state.Progress) + amount;
	state.Progress = static_cast<int>(std::min<long long>(
		task->TargetCount,
		nextProgress));
	if (state.Progress < task->TargetCount)
		return {};

	if (state.AwardCount < std::numeric_limits<int>::max())
		++state.AwardCount;
	return SP_MakeTaskExpGain(*task);
}

static SPTaskExpGain SP_ApplyParentChildEvent(
	UINT uin,
	const SPRuntimeCfg& cfg,
	int parentTaskID,
	int childTaskID,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	const SPTaskCfg* parent = SP_FindTaskCfg(cfg, parentTaskID);
	if (!parent)
		return {};
	const SPChildTaskCfg* child =
		SP_FindChildTaskCfg(*parent, childTaskID);
	if (!child)
		return {};

	SpeedPassTaskStateRow& childState = SP_GetChangedTaskState(
		uin,
		cfg,
		child->TaskID,
		child->ExecutePeriod,
		changedStates);
	childState.Progress = child->TargetCount;
	if (childState.AwardCount < std::numeric_limits<int>::max())
		++childState.AwardCount;

	SpeedPassTaskStateRow& parentState = SP_GetChangedTaskState(
		uin,
		cfg,
		parent->TaskID,
		parent->ExecutePeriod,
		changedStates);
	if (parent->ShExecuteNum > 0 &&
		parentState.AwardCount >= parent->ShExecuteNum)
	{
		return {};
	}

	if (parentState.Progress < parent->TargetCount)
		++parentState.Progress;
	if (parentState.Progress < parent->TargetCount)
		return {};

	if (parentState.AwardCount < std::numeric_limits<int>::max())
		++parentState.AwardCount;
	return SP_MakeTaskExpGain(*parent);
}

static int SP_CurrentDate()
{
	const time_t now = time(nullptr);
	struct tm localNow = {};
	localtime_s(&localNow, &now);
	return
		(localNow.tm_year + 1900) * 10000 +
		(localNow.tm_mon + 1) * 100 +
		localNow.tm_mday;
}

static SPTaskExpGain SP_ApplySprintTask(
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& state,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	const SPTaskCfg* task = SP_FindTaskCfg(cfg, 5701);
	if (!task ||
		task->PassTaskType != 1 ||
		!SP_HasPaidPass(cfg, state) ||
		task->PassTaskMaxLevel <= 0 ||
		state.CurLevel >= task->PassTaskMaxLevel)
	{
		return {};
	}

	const int currentDate = SP_CurrentDate();
	if (currentDate < task->OpenDate ||
		currentDate > task->CloseDate)
	{
		return {};
	}
	return SP_ApplyRepeatTask(
		uin,
		cfg,
		task->TaskID,
		changedStates);
}

static SPTaskExpGain SP_ApplyOfficialRaceTasks(
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& state,
	bool ranked,
	bool border,
	bool trackWorkshop,
	int finishRank,
	bool champion,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	changedStates.clear();
	changedStates.reserve(32);

	SPTaskExpGain gain = SP_ApplyRepeatTask(
		uin,
		cfg,
		5700,
		changedStates);
	gain += SP_ApplyParentChildEvent(
		uin,
		cfg,
		5702,
		5666,
		changedStates);
	gain += SP_ApplyParentChildEvent(
		uin,
		cfg,
		5703,
		5668,
		changedStates);

	if (ranked)
	{
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5704, 5670, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5705, 5672, changedStates);
	}
	if (border)
	{
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5704, 5671, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5705, 5673, changedStates);
	}
	if (trackWorkshop)
	{
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5706, 5682, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5707, 5685, changedStates);
	}
	if (champion)
	{
		gain += SP_ApplyDirectTaskProgress(
			uin, cfg, 5688, 1, changedStates);
		gain += SP_ApplyDirectTaskProgress(
			uin, cfg, 5689, 1, changedStates);
		gain += SP_ApplyDirectTaskProgress(
			uin, cfg, 5690, 1, changedStates);
	}
	if (ranked && champion)
	{
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5708, 5691, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5709, 5693, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5710, 5695, changedStates);
	}
	if (border && finishRank >= 1 && finishRank <= 3)
	{
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5708, 5692, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5709, 5694, changedStates);
		gain += SP_ApplyParentChildEvent(
			uin, cfg, 5710, 5696, changedStates);
	}
	gain += SP_ApplySprintTask(
		uin,
		cfg,
		state,
		changedStates);
	return gain;
}

static SPTaskExpGain SP_ApplyOfficialDanceTasks(
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& state,
	UINT perfectCount,
	std::vector<SpeedPassTaskStateRow>& changedStates)
{
	changedStates.clear();
	changedStates.reserve(12);

	SPTaskExpGain gain = SP_ApplyRepeatTask(
		uin,
		cfg,
		5700,
		changedStates);
	const SPTaskCfg* weeklyTask = SP_FindTaskCfg(cfg, 5702);
	const SPChildTaskCfg* danceChild = weeklyTask
		? SP_FindChildTaskCfg(*weeklyTask, 5667)
		: nullptr;
	if (danceChild &&
		perfectCount >= static_cast<UINT>(danceChild->TargetCount))
	{
		gain += SP_ApplyParentChildEvent(
			uin,
			cfg,
			5702,
			5667,
			changedStates);
		gain += SP_ApplyParentChildEvent(
			uin,
			cfg,
			5703,
			5669,
			changedStates);
	}
	gain += SP_ApplySprintTask(
		uin,
		cfg,
		state,
		changedStates);
	return gain;
}

static bool SP_CommitTaskEvent(
	std::shared_ptr<ClientNode> Client,
	const SPRuntimeCfg& cfg,
	const char* eventName,
	const SPTaskExpGain& gain,
	std::vector<SpeedPassTaskStateRow>& changedTaskStates,
	SpeedPassStateRow& state,
	bool publishSettlement)
{
	if (!Client || changedTaskStates.empty())
		return false;

	const SpeedPassStateRow beginState = state;
	const int appliedExp = SP_ApplyTaskExp(cfg, state, gain);
	if (!PlayerDB_SPCommitStateAndTasks(
		Client->Uin,
		cfg.ActivityID,
		state,
		changedTaskStates))
	{
		QQS_DebugPrintf10001(
			"[SpeedPass] %s task transaction failed Uin=%u EarnedExp=%d Rows=%zu\n",
			eventName,
			Client->Uin,
			gain.Total(),
			changedTaskStates.size());
		return false;
	}

	if (publishSettlement)
	{
		SPSettlementRecord settlement;
		settlement.GameBeginLevel = beginState.CurLevel;
		settlement.GameBeginExp = beginState.CurExp;
		settlement.AddExp = appliedExp;
		settlement.CurrentState = state;
		std::lock_guard<std::mutex> lock(g_SPSettlementMutex);
		g_SPPendingSettlements[Client->Uin] = settlement;
	}

	QQS_DebugPrintf10001(
		"[SpeedPass] %s tasks committed Uin=%u WeeklyExp=%d SeasonExp=%d "
		"AppliedExp=%d WeekScore=%d->%d Level=%d->%d Exp=%d->%d TaskRows=%zu\n",
		eventName,
		Client->Uin,
		gain.Weekly,
		gain.Season,
		appliedExp,
		beginState.WeekTaskCurScore,
		state.WeekTaskCurScore,
		beginState.CurLevel,
		state.CurLevel,
		beginState.CurExp,
		state.CurExp,
		changedTaskStates.size());
	return true;
}

void SP_AddRaceResult(
	std::shared_ptr<ClientNode> Client,
	bool ranked,
	bool border,
	bool trackWorkshop,
	int finishRank,
	bool champion)
{
	if (!Client || finishRank <= 0)
		return;

	SPRuntimeCfg cfg = SP_LoadRuntimeCfg();
	if (!SP_IsActive(cfg))
		return;

	SpeedPassStateRow state = SP_LoadState(Client->Uin, cfg);
	std::vector<SpeedPassTaskStateRow> changedTaskStates;
	const SPTaskExpGain gain = SP_ApplyOfficialRaceTasks(
		Client->Uin,
		cfg,
		state,
		ranked,
		border,
		trackWorkshop,
		finishRank,
		champion,
		changedTaskStates);
	SP_CommitTaskEvent(
		Client,
		cfg,
		"race",
		gain,
		changedTaskStates,
		state,
		true);
}

