static void SP_AppendNotifyItem(std::vector<ItemInfo>& notifyItems, const SPRewardItemCfg& cfgItem, int finalNum)
{
	ItemInfo item; item.ItemID = (UINT)cfgItem.ItemID; item.ItemNum = (finalNum > 0 && cfgItem.ItemType == 0) ? finalNum : cfgItem.ItemNum; item.AvailPeriod = cfgItem.AvailPeriod; item.Status = 0; item.ObtainTime = (int)time(nullptr); item.OtherAttribute = 0; item.ItemType = cfgItem.ItemType > 0 ? cfgItem.ItemType : (int)GetItemType((UINT)cfgItem.ItemID); notifyItems.push_back(item);
}
struct SPClaimStats { int Eligible = 0; int AlreadyClaimed = 0; int LockedTier = 0; int BlockedLevel = 0; int EmptyReward = 0; int Granted = 0; int BadRequest = 0; };
struct SPAwardOptRequest { bool HasAward = false; int PassLevel = 0; int PassType = 0; std::vector<int> DebugNums; };

static std::string SP_FormatNumsForLog(const std::vector<int>& nums)
{
	std::string out;
	for (size_t i = 0; i < nums.size(); ++i)
	{
		if (i) out.push_back(',');
		out += std::to_string(nums[i]);
	}
	return out;
}
static std::string SP_ToLowerKey(std::string s)
{
	std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) { return (char)std::tolower(c); });
	return s;
}
static bool SP_KeyIsPassLevel(const std::string& key)
{
	std::string k = SP_ToLowerKey(key);
	return k == "pass_level" || k == "passlevel" || k == "level" || k == "passlev" || k == "m_uipasslevel" || k == "m_ucpasslevel";
}
static bool SP_KeyIsPassType(const std::string& key)
{
	std::string k = SP_ToLowerKey(key);
	return k == "pass_type" || k == "passtype" || k == "type" || k == "passtier" || k == "m_uipass_type" || k == "m_ucpasstype";
}
static SPAwardOptRequest SP_ParseAwardOptRequest(BYTE* msg, size_t msgLen, int maxLevel)
{
	SPAwardOptRequest req;
	std::vector<std::string> dict;
	std::string pendingKey;
	std::vector<int> allNums;
	for (size_t i = CT_FindQuickRpcPayload(msg, msgLen); i < msgLen;)
	{
		BYTE tag = msg[i];
		if (tag == 250 && i + 2 <= msgLen)
		{
			BYTE len = msg[i + 1];
			if (i + 2 + len > msgLen) break;
			pendingKey.assign(reinterpret_cast<const char*>(msg + i + 2), len);
			dict.push_back(pendingKey);
			i += 2 + len;
			continue;
		}
		if (tag == 251 && i + 2 <= msgLen)
		{
			BYTE idx = msg[i + 1];
			pendingKey = (idx < dict.size()) ? dict[idx] : std::string();
			i += 2;
			continue;
		}
		if (tag == 253 && i + 5 <= msgLen)
		{
			pendingKey.clear();
			i += 5;
			continue;
		}
		if (tag == 246 && i + 9 <= msgLen)
		{
			int value = CT_RoundToInt(CT_ReadDoubleValue(msg + i + 1));
			allNums.push_back(value);
			if (SP_KeyIsPassLevel(pendingKey) && value >= 1 && value <= maxLevel)
			{
				req.PassLevel = value;
				req.HasAward = true;
			}
			else if (SP_KeyIsPassType(pendingKey) && value >= 1 && value <= 3)
			{
				req.PassType = value;
				req.HasAward = true;
			}
			pendingKey.clear();
			i += 9;
			continue;
		}
		++i;
	}

	// 部分客户端点击单格时只带紧凑数字，不带可识别 key；单格请求明显比一键领取长。
	// 这里只标记为“单格请求”，但后续必须同时有 pass_type + pass_level 才允许发奖。
	if (!req.HasAward && msgLen >= 80 && allNums.size() >= 3)
	{
		for (size_t i = 1; i < allNums.size(); ++i)
		{
			int v = allNums[i];
			if (v >= 1 && v <= 3 && req.PassType <= 0) req.PassType = v;
			else if (v >= 1 && v <= maxLevel && req.PassLevel <= 0) req.PassLevel = v;
		}
		if (req.PassType > 0 || req.PassLevel > 0) req.HasAward = true;
	}
	req.DebugNums = allNums;
	return req;
}
static const SPPassTierCfg* SP_FindPassByType(const SPRuntimeCfg& cfg, int passType)
{
	for (const auto& tier : cfg.Passes) if (tier.PassType == passType) return &tier;
	return nullptr;
}

static std::string SP_UnlockAwardClaimTier(const SPPassTierCfg& tier)
{
	return std::string("unlock_") + tier.Tier;
}

static bool SP_UnlockAwardContainsItem(const SPPassTierCfg& tier, int itemID)
{
	return std::any_of(
		tier.ShowUnlockAward.begin(),
		tier.ShowUnlockAward.end(),
		[itemID](const SPRewardItemCfg& item) { return item.ItemID == itemID; });
}

static int SP_GrantPassUnlockAwards(
	const std::shared_ptr<ClientNode>& Client,
	const SPRuntimeCfg& cfg,
	const SPPassTierCfg& tier,
	const SPPassTierCfg* inheritedTier)
{
	if (!Client || tier.PassType < 2 || tier.ShowUnlockAward.empty())
		return 0;

	const std::string claimTier = SP_UnlockAwardClaimTier(tier);
	const std::string inheritedClaimTier =
		inheritedTier ? SP_UnlockAwardClaimTier(*inheritedTier) : std::string();
	std::vector<ItemInfo> notifyItems;
	int grantedCount = 0;

	for (const auto& item : tier.ShowUnlockAward)
	{
		if (item.ItemID <= 0 || item.ItemNum <= 0)
			continue;
		if (PlayerDB_SPIsClaimed(
				Client->Uin,
				cfg.ActivityID,
				claimTier,
				item.ItemID))
			continue;

		// 典藏档包含尊享档的预览道具。玩家从尊享升级典藏时，
		// 已经发过的同一道具只继承领取标记，不能重复入库。
		if (inheritedTier &&
			SP_UnlockAwardContainsItem(*inheritedTier, item.ItemID) &&
			PlayerDB_SPIsClaimed(
				Client->Uin,
				cfg.ActivityID,
				inheritedClaimTier,
				item.ItemID))
		{
			PlayerDB_SPMarkClaimed(
				Client->Uin,
				cfg.ActivityID,
				claimTier,
				item.ItemID);
			continue;
		}

		const int finalNum = PlayerDB_AddItem2(
			Client,
			Client->Uin,
			static_cast<DWORD>(item.ItemID),
			static_cast<DWORD>(item.ItemNum),
			item.AvailPeriod,
			false);
		const int persistedNum = PlayerDB_GetItemNum(
			Client->Uin,
			static_cast<DWORD>(item.ItemID));
		if (persistedNum <= 0)
		{
			QQS_DebugPrintf10001(
				"[SpeedPass] unlock award add failed Uin=%u PassType=%d "
				"ItemID=%d ItemNum=%d\n",
				Client->Uin,
				tier.PassType,
				item.ItemID,
				item.ItemNum);
			continue;
		}

		PlayerDB_SPMarkClaimed(
			Client->Uin,
			cfg.ActivityID,
			claimTier,
			item.ItemID);
		if (!PlayerDB_SPIsClaimed(
			Client->Uin,
			cfg.ActivityID,
			claimTier,
			item.ItemID))
		{
			QQS_DebugPrintf10001(
				"[SpeedPass] unlock award claim mark failed Uin=%u "
				"PassType=%d ItemID=%d\n",
				Client->Uin,
				tier.PassType,
				item.ItemID);
		}

		SP_AppendNotifyItem(
			notifyItems,
			item,
			finalNum > 0 ? finalNum : persistedNum);
		++grantedCount;
	}

	if (!notifyItems.empty())
		NotifyClientAddItem(
			Client,
			static_cast<UINT>(notifyItems.size()),
			notifyItems);
	return grantedCount;
}

static int SP_ReconcilePassUnlockAwards(
	const std::shared_ptr<ClientNode>& Client,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& state)
{
	const SPPassTierCfg* premium = SP_FindPassByType(cfg, 2);
	const SPPassTierCfg* collection = SP_FindPassByType(cfg, 3);
	if (collection && state.CollectionUnlocked != 0)
		return SP_GrantPassUnlockAwards(
			Client,
			cfg,
			*collection,
			premium);
	if (premium && state.PremiumUnlocked != 0)
		return SP_GrantPassUnlockAwards(
			Client,
			cfg,
			*premium,
			nullptr);
	return 0;
}

enum class SPPurchaseCommitResult
{
	Success,
	NoCurrency,
	CurrencyUnavailable,
	DatabaseError
};

static void SP_AddPurchasedLevels(SpeedPassStateRow& state, int addLevel, int maxLevel)
{
	if (state.CurLevel < 1) state.CurLevel = 1;
	if (addLevel <= 0) return;
	state.CurLevel += addLevel;
	if (state.CurLevel >= maxLevel)
	{
		state.CurLevel = maxLevel;
		state.CurExp = 0;
	}
}

static SPPurchaseCommitResult SP_CommitSpeedCoinPurchase(
	const std::shared_ptr<ClientNode>& Client,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& nextState,
	UINT cost,
	UINT& balanceAfter)
{
	if (!Client || cost == 0)
		return SPPurchaseCommitResult::DatabaseError;

	const SpeedPassPurchaseDbResult dbResult = PlayerDB_SPTryPurchase(
		Client->Uin,
		cfg.ActivityID,
		cost,
		nextState,
		balanceAfter);
	if (dbResult != SpeedPassPurchaseDbResult::Success)
	{
		if (dbResult != SpeedPassPurchaseDbResult::CurrencyUnavailable)
			Client->SpeedCoin = balanceAfter;
		if (dbResult == SpeedPassPurchaseDbResult::InsufficientFunds)
			return SPPurchaseCommitResult::NoCurrency;
		if (dbResult == SpeedPassPurchaseDbResult::CurrencyUnavailable)
			return SPPurchaseCommitResult::CurrencyUnavailable;
		return SPPurchaseCommitResult::DatabaseError;
	}

	Client->SpeedCoin = balanceAfter;
	NotifyClientUpdateMoney(Client);
	return SPPurchaseCommitResult::Success;
}

static std::vector<SPGrantedItem> SP_ClaimSingleReward(std::shared_ptr<ClientNode> Client, const SPRuntimeCfg& cfg, SpeedPassStateRow& st, const SPAwardOptRequest& req, SPClaimStats* stats)
{
	std::vector<SPGrantedItem> granted;
	if (!Client || req.PassLevel <= 0 || req.PassType <= 0) { if (stats) ++stats->BadRequest; return granted; }
	const SPPassTierCfg* tier = SP_FindPassByType(cfg, req.PassType);
	const SPRewardLevelCfg* row = SP_FindRewardLevel(cfg, req.PassLevel);
	if (!tier || !row) { if (stats) ++stats->EmptyReward; return granted; }
	const auto& items = SP_TierRewards(*row, tier->Tier);
	if (items.empty()) { if (stats) ++stats->EmptyReward; return granted; }
	if (req.PassLevel > st.CurLevel) { if (stats) ++stats->BlockedLevel; return granted; }
	if (!SP_IsTierUnlocked(st, *tier)) { if (stats) ++stats->LockedTier; return granted; }
	if (stats) ++stats->Eligible;
	if (PlayerDB_SPIsClaimed(Client->Uin, cfg.ActivityID, tier->Tier, req.PassLevel)) { if (stats) ++stats->AlreadyClaimed; return granted; }

	std::vector<ItemInfo> notifyItems;
	bool any = false;
	for (const auto& item : items)
	{
		if (item.ItemID <= 0 || item.ItemNum <= 0) continue;
		int finalNum = PlayerDB_AddItem2(Client, Client->Uin, (DWORD)item.ItemID, (DWORD)item.ItemNum, item.AvailPeriod, false);
		SP_AppendNotifyItem(notifyItems, item, finalNum);
		SPGrantedItem gi; gi.Item = item; gi.Level = req.PassLevel; gi.PassType = tier->PassType; gi.Tier = tier->Tier; granted.push_back(gi); any = true;
	}
	if (any)
	{
		PlayerDB_SPMarkClaimed(Client->Uin, cfg.ActivityID, tier->Tier, req.PassLevel);
		if (stats) ++stats->Granted;
		if (!notifyItems.empty()) NotifyClientAddItem(Client, (UINT)notifyItems.size(), notifyItems);
	}
	return granted;
}

static std::vector<SPGrantedItem> SP_ClaimAvailableRewards(std::shared_ptr<ClientNode> Client, const SPRuntimeCfg& cfg, SpeedPassStateRow& st, SPClaimStats* stats)
{
	std::vector<SPGrantedItem> granted; if (!Client) return granted; std::vector<ItemInfo> notifyItems;
	for (int level = 1; level <= cfg.MaxLevel; ++level)
	{
		const SPRewardLevelCfg* row = SP_FindRewardLevel(cfg, level); if (!row) continue;
		for (const auto& tier : cfg.Passes)
		{
			const auto& items = SP_TierRewards(*row, tier.Tier);
			if (items.empty()) { if (stats) ++stats->EmptyReward; continue; }
			if (level > st.CurLevel) { if (stats) ++stats->BlockedLevel; continue; }
			if (!SP_IsTierUnlocked(st, tier)) { if (stats) ++stats->LockedTier; continue; }
			if (stats) ++stats->Eligible;
			if (PlayerDB_SPIsClaimed(Client->Uin, cfg.ActivityID, tier.Tier, level)) { if (stats) ++stats->AlreadyClaimed; continue; }
			bool any = false;
			for (const auto& item : items)
			{
				if (item.ItemID <= 0 || item.ItemNum <= 0) continue;
				int finalNum = PlayerDB_AddItem2(Client, Client->Uin, (DWORD)item.ItemID, (DWORD)item.ItemNum, item.AvailPeriod, false);
				SP_AppendNotifyItem(notifyItems, item, finalNum);
				SPGrantedItem gi; gi.Item = item; gi.Level = level; gi.PassType = tier.PassType; gi.Tier = tier.Tier; granted.push_back(gi); any = true;
			}
			if (any) { PlayerDB_SPMarkClaimed(Client->Uin, cfg.ActivityID, tier.Tier, level); if (stats) ++stats->Granted; }
		}
	}
	if (!notifyItems.empty()) NotifyClientAddItem(Client, (UINT)notifyItems.size(), notifyItems); return granted;
}
static void SP_WriteGrantedItems(BYTE*& p, const std::vector<SPGrantedItem>& granted)
{
	CT_WriteTextNumber(p, "m_sItemNum", (int)granted.size()); CT_WriteTextNumber(p, "m_iSuperMoney", 0); CT_WriteTextNumber(p, "m_iCoupons", 0);
	CT_WriteKey(p, "m_astItemInfo"); BYTE* len = CT_WriteLenValueStart(p); BYTE* start = p;
	for (size_t i = 0; i < granted.size(); ++i) CT_WriteIndexedObject(p, (int)i + 1, [&](BYTE*& itemP) { CT_WriteTextNumber(itemP, "pass_level", granted[i].Level); CT_WriteTextNumber(itemP, "pass_type", granted[i].PassType); SP_WriteRewardItem(itemP, granted[i].Item); });
	CT_WriteLenValueEnd(len, start, p);
}

static int SP_SettlementRewardStatus(
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& state,
	const SPPassTierCfg& tier,
	int level,
	bool hasReward,
	bool earned)
{
	if (!hasReward || !earned)
		return 0;
	if (!SP_IsTierUnlocked(state, tier))
		return 3;
	return PlayerDB_SPIsClaimed(uin, cfg.ActivityID, tier.Tier, level) ? 2 : 1;
}

static void SP_WriteSettlementAwardLevel(
	BYTE*& p,
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SpeedPassStateRow& state,
	int level,
	bool earned)
{
	const SPRewardLevelCfg* reward = SP_FindRewardLevel(cfg, level);
	static const std::vector<SPRewardItemCfg> empty;
	CT_WriteTextNumber(p, "pass_level", level);
	CT_WriteTextNumber(p, "specialFlag", reward ? reward->SpecialFlag : 0);
	CT_WriteKey(p, "pass_award");
	BYTE* len = CT_WriteLenValueStart(p);
	BYTE* start = p;
	for (size_t i = 0; i < cfg.Passes.size(); ++i)
	{
		const auto& tier = cfg.Passes[i];
		const auto& items =
			reward ? SP_TierRewards(*reward, tier.Tier) : empty;
		const int status = SP_SettlementRewardStatus(
			uin,
			cfg,
			state,
			tier,
			level,
			!items.empty(),
			earned);
		CT_WriteIndexedObject(p, static_cast<int>(i) + 1, [&](BYTE*& passP) {
			CT_WriteTextNumber(passP, "Status", status);
			SP_WriteRewardItemArray(passP, "itemInfos", items);
			CT_WriteTextNumber(passP, "pass_type", tier.PassType);
		});
	}
	CT_WriteLenValueEnd(len, start, p);
}

static void SP_WriteSettlementResponse(
	BYTE*& p,
	UINT uin,
	const SPRuntimeCfg& cfg,
	const SPSettlementRecord& settlement)
{
	const SpeedPassStateRow& state = settlement.CurrentState;
	CT_WriteKey(p, "PlayerInfo");
	BYTE* playerLen = CT_WriteLenValueStart(p);
	BYTE* playerStart = p;
	CT_WriteTextNumber(p, "CurLevel", state.CurLevel);
	CT_WriteTextNumber(p, "CurExp", state.CurExp);
	CT_WriteTextNumber(p, "GameBeginLevel", settlement.GameBeginLevel);
	CT_WriteTextNumber(p, "GameBeginExp", settlement.GameBeginExp);
	CT_WriteTextNumber(p, "NeedExp", SP_GetNeedExp(cfg, state.CurLevel));
	CT_WriteTextNumber(p, "AddExp", settlement.AddExp);
	CT_WriteLenValueEnd(playerLen, playerStart, p);

	CT_WriteKey(p, "AwardInfo");
	BYTE* awardLen = CT_WriteLenValueStart(p);
	BYTE* awardStart = p;
	CT_WriteIndexedObject(p, 1, [&](BYTE*& levelP) {
		SP_WriteSettlementAwardLevel(
			levelP,
			uin,
			cfg,
			state,
			state.CurLevel,
			true);
	});
	if (state.CurLevel < cfg.MaxLevel)
	{
		CT_WriteIndexedObject(p, 2, [&](BYTE*& levelP) {
			SP_WriteSettlementAwardLevel(
				levelP,
				uin,
				cfg,
				state,
				state.CurLevel + 1,
				false);
		});
	}
	CT_WriteLenValueEnd(awardLen, awardStart, p);
}

static bool SP_TakePendingSettlement(UINT uin, SPSettlementRecord& settlement)
{
	std::lock_guard<std::mutex> lock(g_SPSettlementMutex);
	auto found = g_SPPendingSettlements.find(uin);
	if (found == g_SPPendingSettlements.end())
		return false;
	settlement = found->second;
	g_SPPendingSettlements.erase(found);
	return true;
}

