void Request_Beta97BattlePassAwardOpt(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (!Client) return;
	SPRuntimeCfg cfg = SP_LoadRuntimeCfg();
	double context = CT_ReadContext(Body, BodyLen);
	SpeedPassStateRow st;
	if (SP_IsActive(cfg)) st = SP_LoadState(Client->Uin, cfg);
	std::vector<int> nums = CT_ParseNumbers(Body, BodyLen);
	const int op = nums.size() > 1 ? nums[1] : 0;
	const int arg = nums.size() > 2 ? nums[2] : 0;

	// 21543 客户端：AwardOpt(4, levelNum) 购买等级，
	// AwardOpt(6, passType) 开通通行证；两条链路都使用飞车币。
	if (op == 4)
	{
		if (!SP_IsActive(cfg) || !cfg.PurchaseEnabled)
		{
			CT_SendDispatchResponse(Client, context, 12173, false, [&](BYTE*& p) { (void)p; });
			return;
		}

		const int levelNum = arg;
		const int configuredLimit = SP_HasPaidPass(cfg, st) ? cfg.AwardMaxNum : cfg.FreeAwardMaxNum;
		const int levelLimit = std::min(cfg.MaxLevel, configuredLimit);
		if (levelNum <= 0 || cfg.BuyLevelSpeedCoinCost <= 0)
		{
			CT_SendDispatchResponse(Client, context, 12172, false, [&](BYTE*& p) { (void)p; });
			return;
		}
		if (st.CurLevel >= levelLimit || levelNum > levelLimit - st.CurLevel)
		{
			CT_SendDispatchResponse(Client, context, 12705, false, [&](BYTE*& p) { (void)p; });
			return;
		}

		const unsigned long long cost64 =
			static_cast<unsigned long long>(cfg.BuyLevelSpeedCoinCost) *
			static_cast<unsigned long long>(levelNum);
		if (cost64 == 0 || cost64 > std::numeric_limits<UINT>::max())
		{
			CT_SendDispatchResponse(Client, context, 12172, false, [&](BYTE*& p) { (void)p; });
			return;
		}

		SpeedPassStateRow nextState = st;
		SP_AddPurchasedLevels(nextState, levelNum, cfg.MaxLevel);
		UINT balanceAfter = 0;
		const SPPurchaseCommitResult result = SP_CommitSpeedCoinPurchase(
			Client,
			cfg,
			nextState,
			static_cast<UINT>(cost64),
			balanceAfter);
		if (result != SPPurchaseCommitResult::Success)
		{
			const int errorCode = result == SPPurchaseCommitResult::NoCurrency ? 12295 : 12113;
			CT_SendDispatchResponse(Client, context, errorCode, false, [&](BYTE*& p) { (void)p; });
			QQS_DebugPrintf10001(
				"[SpeedPass] BuyLevel failed Uin=%u Num=%d Cost=%llu "
				"Result=%d SpeedCoin=%u Level=%d\n",
				Client->Uin,
				levelNum,
				cost64,
				static_cast<int>(result),
				balanceAfter,
				st.CurLevel);
			return;
		}

		CT_SendDispatchResponse(Client, context, 0, true, [&](BYTE*& p) { (void)p; });
		QQS_DebugPrintf10001(
			"[SpeedPass] BuyLevel success Uin=%u Num=%d Cost=%llu "
			"SpeedCoin=%u->%u Level=%d->%d\n",
			Client->Uin,
			levelNum,
			cost64,
			balanceAfter + static_cast<UINT>(cost64),
			balanceAfter,
			st.CurLevel,
			nextState.CurLevel);
		return;
	}

	if (op == 6)
	{
		if (!SP_IsActive(cfg) || !cfg.PurchaseEnabled)
		{
			CT_SendDispatchResponse(Client, context, 12173, false, [&](BYTE*& p) { (void)p; });
			return;
		}

		const int passType = arg;
		const SPPassTierCfg* tier = SP_FindPassByType(cfg, passType);
		if (!tier || passType < 2 || passType > 3 || tier->NeedSpeedCoinCost <= 0)
		{
			CT_SendDispatchResponse(Client, context, 12172, false, [&](BYTE*& p) { (void)p; });
			return;
		}

		const bool alreadyUnlocked =
			tier->DefaultUnlocked ||
			(passType == 2 && (st.PremiumUnlocked != 0 || st.CollectionUnlocked != 0)) ||
			(passType == 3 && st.CollectionUnlocked != 0);
		if (alreadyUnlocked)
		{
			SP_ReconcilePassUnlockAwards(Client, cfg, st);
			CT_SendDispatchResponse(Client, context, 12171, false, [&](BYTE*& p) { (void)p; });
			return;
		}

		SpeedPassStateRow nextState = st;
		if (passType == 2)
		{
			nextState.PremiumUnlocked = 1;
		}
		else
		{
			nextState.PremiumUnlocked = 1;
			nextState.CollectionUnlocked = 1;
		}
		SP_AddPurchasedLevels(nextState, tier->UserIncLevel, cfg.MaxLevel);

		UINT balanceAfter = 0;
		const UINT cost = static_cast<UINT>(tier->NeedSpeedCoinCost);
		const SPPurchaseCommitResult result = SP_CommitSpeedCoinPurchase(
			Client,
			cfg,
			nextState,
			cost,
			balanceAfter);
		if (result != SPPurchaseCommitResult::Success)
		{
			const int errorCode = result == SPPurchaseCommitResult::NoCurrency ? 12295 : 12113;
			CT_SendDispatchResponse(Client, context, errorCode, false, [&](BYTE*& p) { (void)p; });
			QQS_DebugPrintf10001(
				"[SpeedPass] BuyPass failed Uin=%u PassType=%d Cost=%u "
				"Result=%d SpeedCoin=%u Level=%d\n",
				Client->Uin,
				passType,
				cost,
				static_cast<int>(result),
				balanceAfter,
				st.CurLevel);
			return;
		}

		const SPPassTierCfg* inheritedTier =
			passType == 3 && st.PremiumUnlocked != 0
			? SP_FindPassByType(cfg, 2)
			: nullptr;
		const int unlockAwardsGranted = SP_GrantPassUnlockAwards(
			Client,
			cfg,
			*tier,
			inheritedTier);
		CT_SendDispatchResponse(Client, context, 0, true, [&](BYTE*& p) { (void)p; });
		QQS_DebugPrintf10001(
			"[SpeedPass] BuyPass success Uin=%u PassType=%d Cost=%u "
			"SpeedCoin=%u->%u Level=%d->%d "
			"Premium=%d Collection=%d UnlockAwards=%d\n",
			Client->Uin,
			passType,
			cost,
			balanceAfter + cost,
			balanceAfter,
			st.CurLevel,
			nextState.CurLevel,
			nextState.PremiumUnlocked,
			nextState.CollectionUnlocked,
			unlockAwardsGranted);
		return;
	}

	SPAwardOptRequest req = SP_ParseAwardOptRequest(Body, BodyLen, cfg.MaxLevel);
	SPClaimStats stats;
	std::vector<SPGrantedItem> granted;
	std::string mode = req.HasAward ? "single" : "batch";
	std::string failReason;

	if (!SP_IsActive(cfg))
	{
		failReason = "config_disabled";
	}
	else if (req.HasAward && (req.PassType <= 0 || req.PassLevel <= 0))
	{
		++stats.BadRequest;
		failReason = "bad_single_request";
	}
	else
	{
		granted = req.HasAward ? SP_ClaimSingleReward(Client, cfg, st, req, &stats) : SP_ClaimAvailableRewards(Client, cfg, st, &stats);
		if (granted.empty())
		{
			if (stats.BadRequest > 0) failReason = "bad_single_request";
			else if (stats.LockedTier > 0) failReason = "locked_tier";
			else if (stats.BlockedLevel > 0) failReason = "blocked_level";
			else if (stats.AlreadyClaimed > 0) failReason = "already_claimed";
			else if (stats.EmptyReward > 0) failReason = "empty_reward";
			else failReason = "no_available_reward";
		}
	}

	QQS_DebugPrintf10001("[SpeedPass] AwardOpt Uin=%u Mode=%s Fail=%s Single=%d ReqPass=%d ReqLevel=%d Eligible=%d AlreadyClaimed=%d LockedTier=%d BlockedLevel=%d Empty=%d Bad=%d GrantedLevels=%d GrantedItems=%zu Level=%d Exp=%d Nums=%s\n",
		Client->Uin, mode.c_str(), failReason.empty() ? "none" : failReason.c_str(), req.HasAward ? 1 : 0, req.PassType, req.PassLevel,
		stats.Eligible, stats.AlreadyClaimed, stats.LockedTier, stats.BlockedLevel, stats.EmptyReward, stats.BadRequest, stats.Granted, granted.size(), st.CurLevel, st.CurExp, SP_FormatNumsForLog(req.DebugNums).c_str());

	if (!failReason.empty())
	{
		CT_SendDispatchResponse(Client, context, 123, false, [&](BYTE*& p) { (void)p; });
		return;
	}
	CT_SendDispatchResponse(Client, context, 0, true, [&](BYTE*& p) { SP_WriteGrantedItems(p, granted); });
}

void Request_Beta99BusinessHotBoxGetGiftBoxInfo(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	YAML::Node cfg = HB_LoadRuntimeCfg();
	std::vector<int> nums = CT_ParseNumbers(Body, BodyLen);
	int defaultActID = HB_YInt(cfg, "default_act_id", 2);
	int defaultGiftBoxID = HB_YInt(cfg, "default_gift_box_id", 62);
	int actID = nums.size() > 1 ? nums[1] : defaultActID;
	int giftBoxID = nums.size() > 2 ? nums[2] : defaultGiftBoxID;
	HB_SendNodeResponse(Client, Body, BodyLen, HB_FindGiftBoxNode(cfg, actID, giftBoxID), "GetGiftBoxInfo");
}

static void CT_SendAddItemNotify(std::shared_ptr<ClientNode> Client, int itemID, int itemNum, int availPeriod, int itemType)
{
	if (!Client || itemNum <= 0) return;

	ItemInfo item;
	item.ItemID = static_cast<UINT>(itemID);
	item.ItemNum = itemNum;
	item.AvailPeriod = availPeriod;
	item.Status = 0;
	item.ObtainTime = static_cast<int>(time(nullptr));
	item.OtherAttribute = 0;
	item.ItemType = itemType;

	NotifyClientAddItem(Client, 1, { item });
}

static void GWB_SendUseItemNotify(std::shared_ptr<ClientNode> Client, int itemID, int useItemNum, int currentItemNum)
{
	if (!Client) return;
	std::vector<BYTE> buf(64);
	BYTE* p = buf.data();
	Write16(p, 18);
	Write32(p, Client->Uin);
	Write32(p, itemID);
	Write32(p, useItemNum);
	Write32(p, currentItemNum);
	size_t len = p - buf.data();
	SendToClient(Client, 556, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
}


