static int XY_YInt(const YAML::Node& node, const char* key, int def)
{
	if (!node || !key || !node[key]) return def;
	try { return node[key].as<int>(); } catch (...) { return def; }
}

static bool XY_YBool(const YAML::Node& node, const char* key, bool def)
{
	if (!node || !key || !node[key]) return def;
	try { return node[key].as<bool>(); } catch (...) { return def; }
}

static bool XY_ReadIntRequired(const YAML::Node& node, const char* key, int& out, std::string& err)
{
	if (!node || !key || !node[key])
	{
		err = std::string("missing field: ") + (key ? key : "");
		return false;
	}
	try
	{
		out = node[key].as<int>();
		return true;
	}
	catch (const std::exception& e)
	{
		err = std::string("invalid field: ") + key + " " + e.what();
		return false;
	}
}

static bool XY_FailConfig(XiyouExplorationConfig& cfg, const std::string& err)
{
	cfg.ConfigLoaded = false;
	cfg.ConfigError = err;
	QQS_DebugPrintf10001("[XiyouExploration] load .\\24251\\XiyouExploration.yml failed, no fallback: %s\n", err.c_str());
	return false;
}

static void XY_LoadDefaultVectors(XiyouExplorationConfig& cfg)
{
	if (cfg.OffsetInfos.empty())
	{
		cfg.OffsetInfos.push_back({ 1, 0 });
		cfg.OffsetInfos.push_back({ 2, 0 });
		cfg.OffsetInfos.push_back({ 3, 0 });
		cfg.OffsetInfos.push_back({ 4, 0 });
	}
	if (cfg.AwardInfos.empty())
	{
		cfg.AwardInfos.push_back({ 0, 1, 1 });
		cfg.AwardInfos.push_back({ 1, 2, 2 });
		cfg.AwardInfos.push_back({ 0, 3, 3 });
	}
	if (cfg.TreasureBoxes.empty())
	{
		cfg.TreasureBoxes.push_back({ 1, 9, 1 });
		cfg.TreasureBoxes.push_back({ 2, 18, 2 });
		cfg.TreasureBoxes.push_back({ 3, 27, 3 });
		cfg.TreasureBoxes.push_back({ 4, 36, 4 });
	}
}

static const XiyouExplorationAwardCfg* XY_FindAwardByIdx(const XiyouExplorationConfig& cfg, int idx)
{
	for (const auto& r : cfg.Awards)
	{
		if (r.Idx == idx) return &r;
	}
	return nullptr;
}

static const XiyouExplorationConfig& XY_LoadConfig()
{
	static XiyouExplorationConfig cfg;
	static bool loaded = false;
	if (loaded) return cfg;
	loaded = true;
	cfg = XiyouExplorationConfig();

	try
	{
		YAML::Node root = YAML::LoadFile(".\\24251\\XiyouExploration.yml");
		YAML::Node xy = root["xiyou_exploration"];
		if (!xy) { XY_FailConfig(cfg, "missing root xiyou_exploration"); return cfg; }

		cfg.Enabled = XY_YBool(xy, "enabled", cfg.Enabled);

		std::string err;
		int v = 0;
		YAML::Node cost = xy["cost"];
		if (!XY_ReadIntRequired(cost, "item_id", v, err) || v <= 0) { XY_FailConfig(cfg, err.empty() ? "invalid cost.item_id" : err); return cfg; }
		cfg.CostItemID = v;
		if (!XY_ReadIntRequired(cost, "once", v, err) || v <= 0) { XY_FailConfig(cfg, err.empty() ? "invalid cost.once" : err); return cfg; }
		cfg.CostOnce = v;
		cfg.CostIncreasePerDraw = XY_YInt(cost, "increase_per_draw", cfg.CostIncreasePerDraw);
		if (cfg.CostIncreasePerDraw < 0) cfg.CostIncreasePerDraw = 0;
		cfg.StrictDrawCost = XY_YBool(cost, "strict_draw_cost", cfg.StrictDrawCost);

		YAML::Node base = xy["base"];
		cfg.PicIndex = XY_YInt(base, "pic_index", cfg.PicIndex);
		cfg.OpenDate = XY_YInt(base, "open_date", cfg.OpenDate);
		cfg.CloseDate = XY_YInt(base, "close_date", cfg.CloseDate);
		cfg.FreezingDate = XY_YInt(base, "freezing_date", cfg.FreezingDate);
		cfg.OpenTime = XY_YInt(base, "open_time", cfg.OpenTime);
		cfg.CloseTime = XY_YInt(base, "close_time", cfg.CloseTime);
		cfg.OffsetMaxCount = XY_YInt(base, "offset_max_count", cfg.OffsetMaxCount);
		cfg.SeasonID = XY_YInt(base, "season_id", cfg.SeasonID);

		YAML::Node box = xy["box"];
		cfg.MinDrawCount = XY_YInt(box, "min_draw_count", cfg.MinDrawCount);
		cfg.InitialAccumulateCount = XY_YInt(box, "initial_accumulate_count", cfg.InitialAccumulateCount);
		cfg.InitialSplDrawCount = XY_YInt(box, "initial_spl_draw_count", cfg.InitialSplDrawCount);
		cfg.AccumulateAddPerDraw = XY_YInt(box, "accumulate_add_per_draw", cfg.AccumulateAddPerDraw);
		cfg.SplDrawDecrement = XY_YInt(box, "spl_draw_decrement", cfg.SplDrawDecrement);

		YAML::Node treasure = xy["treasure"];
		cfg.AccumulateAddPerDraw = XY_YInt(treasure, "add_per_draw", cfg.AccumulateAddPerDraw);
		YAML::Node treasureBoxes = treasure ? treasure["boxes"] : YAML::Node();
		cfg.TreasureBoxes.clear();
		if (treasureBoxes && treasureBoxes.IsSequence())
		{
			for (size_t i = 0; i < treasureBoxes.size(); ++i)
			{
				YAML::Node n = treasureBoxes[i];
				XiyouExplorationTreasureBoxCfg row;
				row.Idx = XY_YInt(n, "idx", static_cast<int>(i + 1));
				row.NeedDraw = XY_YInt(n, "need_draw", cfg.MinDrawCount * static_cast<int>(i + 1));
				row.AwardGroup = XY_YInt(n, "award_group", row.Idx);
				if (row.Idx > 0 && row.NeedDraw > 0 && row.AwardGroup > 0) cfg.TreasureBoxes.push_back(row);
			}
		}

		YAML::Node drawResp = xy["draw_response"];
		cfg.SplBestDrawCount = XY_YInt(drawResp, "spl_best_draw_count", cfg.SplBestDrawCount);
		cfg.AwardInfos.clear();
		YAML::Node awardInfos = drawResp ? drawResp["award_infos"] : YAML::Node();
		if (awardInfos && awardInfos.IsSequence())
		{
			for (size_t i = 0; i < awardInfos.size(); ++i)
			{
				YAML::Node n = awardInfos[i];
				XiyouExplorationAwardInfo row;
				row.Status = XY_YInt(n, "status", 0);
				row.Type = XY_YInt(n, "type", static_cast<int>(i + 1));
				row.EnergyCount = XY_YInt(n, "energy_count", XY_YInt(n, "engrgyCount", static_cast<int>(i + 1)));
				cfg.AwardInfos.push_back(row);
			}
		}

		cfg.OffsetInfos.clear();
		YAML::Node offsets = xy["offset_info"];
		if (offsets && offsets.IsSequence())
		{
			for (size_t i = 0; i < offsets.size(); ++i)
			{
				YAML::Node n = offsets[i];
				XiyouExplorationOffsetInfo row;
				row.Type = XY_YInt(n, "type", static_cast<int>(i + 1));
				row.Value = XY_YInt(n, "value", 0);
				cfg.OffsetInfos.push_back(row);
			}
		}

		YAML::Node awardCfg = xy["award_cfg"];
		YAML::Node defaults = awardCfg ? awardCfg["defaults"] : YAML::Node();
		YAML::Node items = awardCfg ? awardCfg["items"] : YAML::Node();
		if (!items || !items.IsSequence() || items.size() == 0) { XY_FailConfig(cfg, "award_cfg.items empty"); return cfg; }
		cfg.Awards.clear();
		for (size_t i = 0; i < items.size(); ++i)
		{
			YAML::Node n = items[i];
			XiyouExplorationAwardCfg r;
			r.Idx = XY_YInt(n, "idx", static_cast<int>(i + 1));
			r.ItemID = XY_YInt(n, "item_id", XY_YInt(n, "ItemID", 0));
			r.ItemNum = XY_YInt(n, "item_num", XY_YInt(defaults, "item_num", 1));
			r.ItemType = XY_YInt(n, "item_type", XY_YInt(defaults, "item_type", 0));
			r.AvailPeriod = XY_YInt(n, "avail_period", XY_YInt(defaults, "avail_period", -1));
			r.ShowPriority = XY_YInt(n, "show_priority", XY_YInt(defaults, "show_priority", r.Idx));
			r.SuperMoney = XY_YInt(n, "super_money", XY_YInt(defaults, "super_money", 0));
			r.Coupons = XY_YInt(n, "coupons", XY_YInt(defaults, "coupons", 0));
			r.Weight = (std::max)(1, XY_YInt(n, "weight", XY_YInt(defaults, "weight", 100)));
			if (r.Idx <= 0 || r.ItemID <= 0 || r.ItemNum <= 0) { XY_FailConfig(cfg, "invalid award_cfg.items row"); return cfg; }
			cfg.Awards.push_back(r);
		}

		YAML::Node draw = xy["draw"];
		YAML::Node replay = draw ? draw["replay_draws"] : YAML::Node();
		cfg.ReplayDraws.clear();
		if (replay && replay.IsSequence())
		{
			for (size_t i = 0; i < replay.size(); ++i)
			{
				YAML::Node n = replay[i];
				XiyouExplorationReplayDraw r;
				r.DrawNo = XY_YInt(n, "draw_no", 0);
				r.Award.Idx = XY_YInt(n, "award_idx", XY_YInt(n, "idx", 0));
				const XiyouExplorationAwardCfg* baseAward = XY_FindAwardByIdx(cfg, r.Award.Idx);
				if (baseAward) r.Award = *baseAward;
				r.Award.Idx = XY_YInt(n, "award_idx", XY_YInt(n, "idx", r.Award.Idx));
				r.Award.ItemID = XY_YInt(n, "item_id", r.Award.ItemID);
				r.Award.ItemNum = XY_YInt(n, "item_num", r.Award.ItemNum > 0 ? r.Award.ItemNum : 1);
				r.Award.ItemType = XY_YInt(n, "item_type", r.Award.ItemType);
				r.Award.AvailPeriod = XY_YInt(n, "avail_period", r.Award.AvailPeriod);
				r.Award.ShowPriority = XY_YInt(n, "show_priority", r.Award.ShowPriority > 0 ? r.Award.ShowPriority : r.Award.Idx);
				r.Award.SuperMoney = XY_YInt(n, "super_money", r.Award.SuperMoney);
				r.Award.Coupons = XY_YInt(n, "coupons", r.Award.Coupons);
				if (r.DrawNo <= 0 || r.Award.Idx <= 0 || r.Award.ItemID <= 0 || r.Award.ItemNum <= 0) { XY_FailConfig(cfg, "invalid draw.replay_draws row"); return cfg; }
				cfg.ReplayDraws.push_back(r);
			}
		}

		YAML::Node boxAwards = xy["box_awards"];
		YAML::Node boxDefaults = boxAwards ? boxAwards["defaults"] : YAML::Node();
		YAML::Node groups = boxAwards ? boxAwards["groups"] : YAML::Node();
		cfg.BoxAwards.clear();
		if (groups && groups.IsMap())
		{
			for (auto it = groups.begin(); it != groups.end(); ++it)
			{
				int groupId = 0;
				try { groupId = it->first.as<int>(); } catch (...) { continue; }
				YAML::Node rowsNode = it->second;
				if (groupId <= 0 || !rowsNode || !rowsNode.IsSequence()) continue;
				std::vector<XiyouExplorationBoxAwardCfg> rows;
				for (size_t i = 0; i < rowsNode.size(); ++i)
				{
					YAML::Node n = rowsNode[i];
					XiyouExplorationBoxAwardCfg row;
					row.ItemID = XY_YInt(n, "item_id", 0);
					row.ItemNum = XY_YInt(n, "item_num", XY_YInt(boxDefaults, "item_num", 1));
					row.ItemType = XY_YInt(n, "item_type", XY_YInt(boxDefaults, "item_type", 0));
					row.AvailPeriod = XY_YInt(n, "avail_period", XY_YInt(boxDefaults, "avail_period", 0));
					row.Piece = XY_YInt(n, "piece", XY_YInt(boxDefaults, "piece", 0));
					if (row.ItemID > 0 && row.ItemNum > 0) rows.push_back(row);
				}
				if (!rows.empty()) cfg.BoxAwards[groupId] = rows;
			}
		}

		XY_LoadDefaultVectors(cfg);
		cfg.ConfigLoaded = true;
		cfg.ConfigError.clear();
		QQS_DebugPrintf10001("[XiyouExploration] loaded .\\24251\\XiyouExploration.yml Awards=%zu Replay=%zu CostItem=%d\n", cfg.Awards.size(), cfg.ReplayDraws.size(), cfg.CostItemID);
	}
	catch (const std::exception& e)
	{
		XY_FailConfig(cfg, e.what());
	}
	return cfg;
}

static int XY_CostForDraw(const XiyouExplorationConfig& cfg, int curDraw)
{
	int cost = cfg.CostOnce + ((std::max)(0, curDraw) * cfg.CostIncreasePerDraw);
	return (std::max)(1, cost);
}

static int XY_AccumulateCount(const XiyouExplorationConfig& cfg, int curDraw)
{
	return cfg.InitialAccumulateCount + ((std::max)(0, curDraw) * cfg.AccumulateAddPerDraw);
}

static UINT XY_BoxBit(int idx)
{
	return (idx > 0 && idx <= 31) ? (1u << (idx - 1)) : 0u;
}

static bool XY_IsBoxClaimed(const XiyouExplorationState& state, int idx)
{
	UINT bit = XY_BoxBit(idx);
	return bit != 0 && ((state.BoxClaimMask & bit) != 0);
}

static void XY_MarkBoxClaimed(XiyouExplorationState& state, int idx)
{
	UINT bit = XY_BoxBit(idx);
	if (bit != 0) state.BoxClaimMask |= bit;
}

static int XY_BoxStatus(const XiyouExplorationState& state, const XiyouExplorationTreasureBoxCfg& box)
{
	if (XY_IsBoxClaimed(state, box.Idx)) return 2;
	return state.DrawCount >= box.NeedDraw ? 1 : 0;
}

static const XiyouExplorationTreasureBoxCfg* XY_FindTreasureBox(const XiyouExplorationConfig& cfg, int idx)
{
	for (const auto& box : cfg.TreasureBoxes)
	{
		if (box.Idx == idx) return &box;
	}
	return nullptr;
}

static const XiyouExplorationTreasureBoxCfg* XY_FirstEligibleTreasureBox(const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	for (const auto& box : cfg.TreasureBoxes)
	{
		if (state.DrawCount >= box.NeedDraw && !XY_IsBoxClaimed(state, box.Idx)) return &box;
	}
	return nullptr;
}

static int XY_SplDrawCount(const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	for (const auto& box : cfg.TreasureBoxes)
	{
		if (XY_IsBoxClaimed(state, box.Idx)) continue;
		if (state.DrawCount >= box.NeedDraw) return 0;
		return (std::max)(0, box.NeedDraw - state.DrawCount);
	}
	return 0;
}

static bool XY_HasGotAward(const XiyouExplorationState& state, int awardIdx)
{
	return std::find(state.GotAwardIdx.begin(), state.GotAwardIdx.end(), awardIdx) != state.GotAwardIdx.end();
}

static void XY_MarkGotAward(XiyouExplorationState& state, int awardIdx)
{
	if (awardIdx <= 0 || XY_HasGotAward(state, awardIdx)) return;
	state.GotAwardIdx.push_back(awardIdx);
}

static void XY_WriteFdBlock(BYTE*& p, const std::function<void(BYTE*&)>& writer)
{
	BYTE* len = CT_WriteLenValueStart(p);
	BYTE* start = p;
	writer(p);
	CT_WriteLenValueEnd(len, start, p);
}

static void XY_WriteBoolValue(BYTE*& p, const char* key, bool value)
{
	CT_WriteKey(p, key);
	if (value) WriteF8(p); else WriteF9(p);
}

static void XY_WriteAwardCfg(BYTE*& p, const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	CT_WriteKey(p, "AwardCfg");
	XY_WriteFdBlock(p, [&](BYTE*& a) {
		for (const auto& r : cfg.Awards)
		{
			CT_WriteIndexedObject(a, r.Idx, [&](BYTE*& item) {
				CT_WriteTextNumber(item, "m_iAvailPeriod", r.AvailPeriod);
				CT_WriteTextNumber(item, "m_ushItemType", r.ItemType);
				CT_WriteTextNumber(item, "m_iSuperMoney", r.SuperMoney);
				CT_WriteTextNumber(item, "m_iItemID", r.ItemID);
				CT_WriteTextNumber(item, "m_usShowPriority", r.ShowPriority);
				CT_WriteTextNumber(item, "m_iCoupons", r.Coupons);
				XY_WriteBoolValue(item, "m_bAlreadGot", XY_HasGotAward(state, r.Idx));
				CT_WriteTextNumber(item, "m_iItemNum", r.ItemNum);
			});
		}
	});
}

static void XY_WritePlayerInfo(BYTE*& p, std::shared_ptr<ClientNode> Client, const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	int haveDrawItem = (Client && cfg.CostItemID > 0) ? PlayerDB_GetItemNum(Client->Uin, cfg.CostItemID) : 0;
	CT_WriteKey(p, "PlayerInfo");
	XY_WriteFdBlock(p, [&](BYTE*& o) {
		CT_WriteTextNumber(o, "costItemNum", XY_CostForDraw(cfg, state.DrawCount));
		CT_WriteTextNumber(o, "curDraw", state.DrawCount);
		CT_WriteTextNumber(o, "drawItemCnt", haveDrawItem);
		CT_WriteTextNumber(o, "drawItemId", cfg.CostItemID);
	});
}

