		CT_WriteTextNumber(o, "OffsetMaxCount", cfg.OffsetMaxCount);
		CT_WriteTextNumber(o, "freezingDate", cfg.FreezingDate);
		CT_WriteTextNumber(o, "openDate", cfg.OpenDate);
