static void XY_WriteBoxInfo(BYTE*& p, const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	CT_WriteKey(p, "BoxInfo");
	XY_WriteFdBlock(p, [&](BYTE*& o) {
		CT_WriteTextNumber(o, "MinDrawCount", cfg.MinDrawCount);
		CT_WriteTextNumber(o, "AccumulateCount", XY_AccumulateCount(cfg, state.DrawCount));
		CT_WriteTextNumber(o, "SplDrawCount", XY_SplDrawCount(cfg, state));
	});
}

static void XY_WriteOffsetInfo(BYTE*& p, const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	std::vector<int> flat;
	if (!cfg.TreasureBoxes.empty())
	{
		flat.reserve(cfg.TreasureBoxes.size() * 2);
		for (const auto& box : cfg.TreasureBoxes)
		{
			flat.push_back(box.Idx);
			flat.push_back(XY_BoxStatus(state, box));
		}
	}
	else
	{
		flat.reserve(cfg.OffsetInfos.size() * 2);
		for (const auto& row : cfg.OffsetInfos)
		{
			flat.push_back(row.Type);
			flat.push_back(row.Value);
		}
	}
	CT_WriteNumberArray(p, "OffsetInfo", flat);
}

static void XY_WriteMainDlgData(BYTE*& p, std::shared_ptr<ClientNode> Client, const XiyouExplorationConfig& cfg, const XiyouExplorationState& state)
{
	XY_WriteAwardCfg(p, cfg, state);
	XY_WritePlayerInfo(p, Client, cfg, state);
	XY_WriteZanCunCfg(p);
	XY_WriteBaseCfg(p, cfg);
	XY_WriteBoxInfo(p, cfg, state);
	XY_WriteOffsetInfo(p, cfg, state);
}

static const XiyouExplorationAwardCfg* XY_PickAward(const XiyouExplorationConfig& cfg, UINT uin, int drawNo)
{
	for (const auto& replay : cfg.ReplayDraws)
	{
		if (replay.DrawNo == drawNo) return &replay.Award;
	}
	if (cfg.Awards.empty()) return nullptr;
	int total = 0;
	for (const auto& r : cfg.Awards) total += (std::max)(1, r.Weight);
	int seed = static_cast<int>(((uin * 1103515245u) + (static_cast<UINT>(drawNo) * 12345u) + 0x82u) % static_cast<UINT>((std::max)(1, total)));
	for (const auto& r : cfg.Awards)
	{
		seed -= (std::max)(1, r.Weight);
		if (seed < 0) return &r;
	}
	return &cfg.Awards.back();
}

static void XY_SendCostItemNotify(std::shared_ptr<ClientNode> Client, int itemId)
{
	if (!Client || itemId <= 0) return;
	std::vector<BYTE> buf(8192);
	BYTE* p = buf.data();
	WORD len = 0;
	WriteRequestHead(p, Client->Uin);
	{
		BYTE* pBody = p;
		Write16(pBody, 0);
		BYTE* pData = WriteBodyHead(pBody);
		BYTE* notifyLen = CT_WriteLenValueStart(pData);
		BYTE* notifyStart = pData;
		WriteValue(pData, 1);
		WriteValue(pData, itemId);
		CT_WriteLenValueEnd(notifyLen, notifyStart, pData);
		WriteBodyHeadEnd(pBody, pData);
		len = static_cast<WORD>(pBody - p);
		Set16(p, len);
		p += len;
	}
	len = static_cast<WORD>(p - buf.data());
	SendToClient(Client, 24251, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);
}

