static int FB_YIntAny(const YAML::Node& node, std::initializer_list<const char*> keys, int def)
{
	if (!node) return def;
	for (const char* key : keys)
	{
		try
		{
			if (!node[key]) continue;
			int intValue = 0;
			if (QQS_YamlTryIntNoThrow(node[key], intValue)) return intValue;
			bool boolValue = false;
			if (QQS_YamlTryBoolNoThrow(node[key], boolValue)) return boolValue ? 1 : 0;
		}
		catch (const std::exception&) {}
	}
	return def;
}

static bool FB_YBoolAny(const YAML::Node& node, std::initializer_list<const char*> keys, bool def)
{
	return FB_YIntAny(node, keys, def ? 1 : 0) != 0;
}

static std::string FB_YStringAny(const YAML::Node& node, std::initializer_list<const char*> keys, const std::string& def)
{
	if (!node) return def;
	for (const char* key : keys)
	{
		try
		{
			if (node[key]) return node[key].as<std::string>();
		}
		catch (const std::exception&) {}
	}
	return def;
}

static std::vector<int> FB_YIntVector(const YAML::Node& node, const std::vector<int>& def)
{
	std::vector<int> values;
	try
	{
		if (node && node.IsSequence())
		{
			for (size_t i = 0; i < node.size(); ++i) values.push_back(node[i].as<int>());
		}
	}
	catch (const std::exception&) {}
	return values.empty() ? def : values;
}

