				Write8(pData, 250);//FA
				Write8(pData, 10);//len
				memcpy(pData, "m_sItemNum", 10);
				pData += 10;

				Write8(pData, 246);//F6
				double intValue = 10;   //总的获奖物品数目
				std::memcpy(pData, &intValue, sizeof(double));
				pData += sizeof(double);  // 移动到下一个数据的位置

