				Write8(pData, 250);//FA
				Write8(pData, 10);//len
				memcpy(pData, "m_iCoupons", 10);
				pData += 10;

				Write8(pData, 246);//F6
				intValue = 0;
				std::memcpy(pData, &intValue, sizeof(double));
