static bool GWB_YBoolAny(const YAML::Node& node, std::initializer_list<const char*> keys, bool def)
{
	if (!node) return def;
	for (const char* key : keys)
	{
		try
		{
			if (!node[key]) continue;
			bool boolValue = false;
			if (QQS_YamlTryBoolNoThrow(node[key], boolValue)) return boolValue;
			int intValue = 0;
			if (QQS_YamlTryIntNoThrow(node[key], intValue)) return intValue != 0;
		}
		catch (const std::exception&) {}
	}
	return def;
}

static std::vector<int> GWB_YIntVector(const YAML::Node& node, const std::vector<int>& def)
{
	std::vector<int> values;
	try
	{
		if (node && node.IsSequence())
		{
			for (const auto& it : node) values.push_back(it.as<int>());
		}
	}
	catch (const std::exception&) {}
	return values.empty() ? def : values;
}

static GodWarBoxAwardCfg GWB_MakeAward(INT idx, UINT itemID, INT itemNum, INT itemType, INT availPeriod, INT fenjieNum, INT probability)
{
	GodWarBoxAwardCfg row;
	row.ItemIndex = idx;
	row.ItemID = itemID;
	row.ItemNum = itemNum;
	row.ItemType = itemType;
	row.AvailPeriod = availPeriod;
	row.FenjieNum = fenjieNum;
	row.Probability = probability;
	return row;
}

