static std::vector<WuHuScoreAwardCfg> WUH_DefaultScoreAwards(const WuHuActivityCfg& cfg)
{
	static const int kNeedScore[] = { 1, 20, 80, 150, 300 };
	static const int kItemNum[] = { 1, 12, 18, 27, 45 };
	std::vector<WuHuScoreAwardCfg> rows;
	for (int i = 0; i < 5; ++i)
	{
		WuHuScoreAwardCfg row;
		row.SpecialFlag = i + 1;
		row.NeedScore = kNeedScore[i];
		WuHuScoreAwardItemCfg item;
		item.ItemID = cfg.FenjieItemID;
		item.ItemNum = kItemNum[i];
		item.ItemType = 0;
		item.AvailPeriod = 0;
		row.Items.push_back(item);
		rows.push_back(row);
	}
	return rows;
}

static void WUH_SetActivity(WuHuRuntimeCfg& rt, const WuHuActivityCfg& cfg)
{
	for (size_t i = 0; i < rt.Activities.size(); ++i)
	{
		if (rt.Activities[i].ActivityType == cfg.ActivityType)
		{
			rt.Activities[i] = cfg;
			return;
		}
	}
	rt.Activities.push_back(cfg);
}

static WuHuRuntimeCfg WUH_DefaultRuntimeCfg()
{
	WuHuRuntimeCfg rt;
	for (size_t i = 0; i < sizeof(kWUH_Activities) / sizeof(kWUH_Activities[0]); ++i)
	{
		const WuHuActivityCfg& cfg = kWUH_Activities[i];
		rt.Activities.push_back(cfg);
		size_t awardCount = 0;
		const WuHuAwardCfg* awards = WUH_AwardsFor(cfg.ActivityType, awardCount);
		rt.AwardsByActivity[cfg.ActivityType].assign(awards, awards + awardCount);
		size_t exchangeCount = 0;
		const WuHuExchangeCfg* exchanges = WUH_ExchangeFor(cfg.ActivityType, exchangeCount);
		rt.ExchangeByActivity[cfg.ActivityType].assign(exchanges, exchanges + exchangeCount);
		rt.ScoreAwardsByActivity[cfg.ActivityType] = WUH_DefaultScoreAwards(cfg);
	}
	return rt;
}

static YAML::Node WUH_LoadRootNode()
{
	const char* paths[] = { ".\\24251\\GodHorseBlessing.yml", ".\\Config\\GodHorseBlessing.yml" };
	for (const char* path : paths)
	{
		try
		{
			YAML::Node file = YAML::LoadFile(path);
			YAML::Node root = file["god_horse_blessing"] ? file["god_horse_blessing"] : file;
			if (root) return root;
		}
		catch (const std::exception&) {}
	}
	return YAML::Node();
}

static const WuHuActivityCfg* WUH_FindActivityRt(const WuHuRuntimeCfg& rt, int activityType)
{
	for (size_t i = 0; i < rt.Activities.size(); ++i)
	{
		if (rt.Activities[i].ActivityType == activityType) return &rt.Activities[i];
	}
	return rt.Activities.empty() ? &WUH_DefaultActivity() : &rt.Activities[0];
}

static const std::vector<WuHuAwardCfg>& WUH_AwardRows(const WuHuRuntimeCfg& rt, int activityType)
{
	static const std::vector<WuHuAwardCfg> emptyRows;
	auto it = rt.AwardsByActivity.find(activityType);
	return it == rt.AwardsByActivity.end() ? emptyRows : it->second;
}

