static int WST_CFGInt(const YAML::Node& node, const char* key, int def)
{
	try { if (node && key && node[key]) return node[key].as<int>(); } catch (const std::exception&) {}
	return def;
}

static bool WST_CFGBool(const YAML::Node& node, const char* key, bool def)
{
	try
	{
		bool out = def;
		if (node && key && node[key] && QQS_YamlTryBoolNoThrow(node[key], out)) return out;
	}
	catch (const std::exception&) {}
	return def;
}

static std::string WST_CFGString(const YAML::Node& node, const char* key, const std::string& def = std::string())
{
	try { if (node && key && node[key]) return node[key].as<std::string>(); } catch (const std::exception&) {}
	return def;
}

static void WST_AddConfigPath(std::vector<std::string>& paths, const std::string& path)
{
	if (path.empty()) return;
	for (size_t i = 0; i < paths.size(); ++i)
	{
		if (_stricmp(paths[i].c_str(), path.c_str()) == 0) return;
	}
	paths.push_back(path);
}

static YAML::Node WST_LoadStructuredYaml(std::string& loadedPath)
{
	std::vector<std::string> paths;
	WST_AddConfigPath(paths, ".\\24251\\WastelandExplory.yml");
	WST_AddConfigPath(paths, ".\\Config\\WastelandExplory.yml");
	WST_AddConfigPath(paths, ".\\WastelandExplory.yml");

	char modulePath[MAX_PATH] = { 0 };
	DWORD moduleLen = GetModuleFileNameA(NULL, modulePath, MAX_PATH);
	if (moduleLen > 0 && moduleLen < MAX_PATH)
	{
		std::string exePath(modulePath, moduleLen);
		size_t slash = exePath.find_last_of("\\/");
		if (slash != std::string::npos)
		{
			std::string exeDir = exePath.substr(0, slash);
			WST_AddConfigPath(paths, exeDir + "\\24251\\WastelandExplory.yml");
			WST_AddConfigPath(paths, exeDir + "\\Config\\WastelandExplory.yml");
			WST_AddConfigPath(paths, exeDir + "\\WastelandExplory.yml");
			WST_AddConfigPath(paths, exeDir + "\\..\\..\\24251\\WastelandExplory.yml");
			WST_AddConfigPath(paths, exeDir + "\\..\\..\\Config\\WastelandExplory.yml");
		}
	}

	for (size_t i = 0; i < paths.size(); ++i)
	{
		try
		{
			YAML::Node file = YAML::LoadFile(paths[i]);
			bool enabled = true;
			if (file && file["enabled"]) QQS_YamlTryBoolNoThrow(file["enabled"], enabled);
			YAML::Node root = file["wasteland_explory"] ? file["wasteland_explory"] : file;
			if (enabled && root && root["activities"])
			{
				loadedPath = paths[i];
				return root;
			}
		}
		catch (const std::exception&) {}
	}
	return YAML::Node();
}

static WSTStructItemCfg WST_ParseStructItem(const YAML::Node& n, int activityType, int defIndex)
{
	WSTStructItemCfg r;
	r.ActivityType = activityType;
	r.Index = WST_CFGInt(n, "index", WST_CFGInt(n, "_index", defIndex));
	r.AwardIdx = WST_CFGInt(n, "award_idx", r.Index);
	r.ItemID = static_cast<UINT>(WST_CFGInt(n, "itemid", WST_CFGInt(n, "item_id", 0)));
	r.ItemNum = WST_CFGInt(n, "itemnum", WST_CFGInt(n, "item_num", 1));
	r.ItemType = WST_CFGInt(n, "item_type", WST_CFGInt(n, "itemtype", 0));
	r.AvailPeriod = WST_CFGInt(n, "availperiod", WST_CFGInt(n, "avail_period", 0));
	r.Coupons = WST_CFGInt(n, "coupons", 0);
	r.SuperMoney = WST_CFGInt(n, "supermoney", WST_CFGInt(n, "super_money", 0));
	r.FenjieNum = WST_CFGInt(n, "fenjie_num", 0);
	r.ExchangeNeedNum = WST_CFGInt(n, "exchangeNeedNum", WST_CFGInt(n, "exchange_need_num", 0));
	r.AwardType = WST_CFGInt(n, "award_type", 1);
	r.Weight = std::max(1, WST_CFGInt(n, "weight", 1));
	r.ToTempBox = WST_CFGBool(n, "to_tempbox", (r.ItemType == 1 || r.ItemType == 2) && r.FenjieNum > 0);
	return r;
}

static WSTStructRuntimeCfg WST_LoadStructCfg()
{
	WSTStructRuntimeCfg cfg;
	std::string path;
	YAML::Node root = WST_LoadStructuredYaml(path);
	if (!root)
	{
		static bool s_loggedMissing = false;
		if (!s_loggedMissing)
		{
			QQS_DebugPrintf10001("[Wasteland] StructCfg missing WastelandExplory.yml\n");
			s_loggedMissing = true;
		}
		return cfg;
	}
	cfg.Loaded = true;
	cfg.Path = path;
	static std::string s_loggedPath;
	if (s_loggedPath != path)
	{
		QQS_DebugPrintf10001("[Wasteland] StructCfg loaded path=%s\n", path.c_str());
		s_loggedPath = path;
	}

	YAML::Node acts = root["activities"];
	if (acts && acts.IsSequence())
	{
		for (size_t i = 0; i < acts.size(); ++i)
		{
			YAML::Node n = acts[i];
			WSTStructActivityCfg a;
			a.ActivityType = WST_CFGInt(n, "activity_type", static_cast<int>(i + 1));
			a.Name = WST_CFGString(n, "name");
			a.SubTitle = WST_CFGString(n, "sub_title");
			a.CostItemID = static_cast<UINT>(WST_CFGInt(n, "cost_item_id", 168226));
			a.BestPieceItemID = static_cast<UINT>(WST_CFGInt(n, "exchange_best_item_id", 0));
			a.FenjieItemID = static_cast<UINT>(WST_CFGInt(n, "fenjie_item_id", 0));
			a.RemindItemID = static_cast<UINT>(WST_CFGInt(n, "remind_item_id", 0));
			a.OpenDate = WST_CFGInt(n, "open_date", a.OpenDate);
			a.OpenTime = WST_CFGInt(n, "open_time", a.OpenTime);
			a.CloseDate = WST_CFGInt(n, "close_date", a.CloseDate);
			a.CloseTime = WST_CFGInt(n, "close_time", a.CloseTime);
			a.SeasonID = WST_CFGInt(n, "season_id", a.SeasonID);
			a.BurstBaoji = WST_CFGInt(n, "burst_baoji", a.BurstBaoji);
			a.CostOne = WST_CFGInt(n, "cost_one", a.CostOne);
			a.CostTen = WST_CFGInt(n, "cost_ten", a.CostTen);
			a.CostFifty = WST_CFGInt(n, "cost_fifty", a.CostFifty);
			cfg.Activities.push_back(a);
		}
	}

	auto parseItemGroups = [&](const char* key, std::vector<WSTStructItemCfg>& out) {
		YAML::Node groups = root[key];
		if (!groups || !groups.IsSequence()) return;
		for (size_t g = 0; g < groups.size(); ++g)
		{
			YAML::Node group = groups[g];
			int activityType = WST_CFGInt(group, "activity_type", 0);
			YAML::Node rows = group["rows"] ? group["rows"] : group["items"];
			if (!rows || !rows.IsSequence()) continue;
			for (size_t i = 0; i < rows.size(); ++i)
			{
				WSTStructItemCfg r = WST_ParseStructItem(rows[i], activityType, static_cast<int>(i + 1));
				if (r.ItemID) out.push_back(r);
			}
		}
	};
	parseItemGroups("info_awards", cfg.InfoAwards);
	parseItemGroups("draw_pool", cfg.DrawPool);

	YAML::Node shops = root["exchange_shop"];
	if (shops && shops.IsSequence())
	{
		for (size_t g = 0; g < shops.size(); ++g)
		{
			YAML::Node group = shops[g];
			int activityType = WST_CFGInt(group, "activity_type", 0);
			YAML::Node rows = group["rows"];
			if (!rows || !rows.IsSequence()) continue;
			for (size_t i = 0; i < rows.size(); ++i)
			{
				YAML::Node n = rows[i];
				WSTStructExchangeCfg r;
				r.ActivityType = activityType;
				r.Index = WST_CFGInt(n, "index", static_cast<int>(i + 1));
				r.AwardIdx = WST_CFGInt(n, "award_idx", r.Index);
				r.ItemID = static_cast<UINT>(WST_CFGInt(n, "itemid", WST_CFGInt(n, "item_id", 0)));
				r.ItemNum = WST_CFGInt(n, "itemnum", WST_CFGInt(n, "item_num", 1));
				r.ItemType = WST_CFGInt(n, "item_type", 0);
				r.AvailPeriod = WST_CFGInt(n, "availperiod", WST_CFGInt(n, "avail_period", -1));
				r.ErrID = WST_CFGInt(n, "errid", 11498);
				r.MaxGetNum = WST_CFGInt(n, "maxGetNum", WST_CFGInt(n, "max_get_num", 1));
				r.RemindFlag = WST_CFGInt(n, "remindFlag", WST_CFGInt(n, "remind_flag", 0));
				r.FenjieNum = WST_CFGInt(n, "fenjie_num", 0);
				YAML::Node costs = n["exchange_items"] ? n["exchange_items"] : n["costs"];
				if (costs && costs.IsSequence())
				{
					for (size_t c = 0; c < costs.size(); ++c)
					{
						WSTStructCostCfg cost;
						cost.PieceID = static_cast<UINT>(WST_CFGInt(costs[c], "piece_id", WST_CFGInt(costs[c], "exchangePieceID", 0)));
						cost.NeedNum = WST_CFGInt(costs[c], "need_num", WST_CFGInt(costs[c], "exchangeNeedNum", 0));
						if (cost.PieceID) r.Costs.push_back(cost);
					}
				}
				if (r.ItemID) cfg.ExchangeRows.push_back(r);
			}
		}
	}

	YAML::Node prog = root["progress_rewards"];
	if (prog && prog.IsSequence())
	{
		for (size_t g = 0; g < prog.size(); ++g)
		{
			YAML::Node group = prog[g];
			int activityType = WST_CFGInt(group, "activity_type", 0);
			YAML::Node rows = group["rows"];
			if (!rows || !rows.IsSequence()) continue;
			for (size_t i = 0; i < rows.size(); ++i)
			{
				YAML::Node n = rows[i];
				WSTStructProgressCfg r;
				r.ActivityType = activityType;
				r.Index = WST_CFGInt(n, "index", static_cast<int>(i + 1));
				r.SpecialFlag = WST_CFGInt(n, "specialFlag", WST_CFGInt(n, "special_flag", r.Index));
				r.NeedScore = WST_CFGInt(n, "needScore", WST_CFGInt(n, "need_score", 0));
				r.ItemID = static_cast<UINT>(WST_CFGInt(n, "itemid", WST_CFGInt(n, "item_id", 0)));
				r.ItemNum = WST_CFGInt(n, "itemnum", WST_CFGInt(n, "item_num", 1));
				r.ItemType = WST_CFGInt(n, "item_type", 0);
				r.AvailPeriod = WST_CFGInt(n, "availperiod", 0);
				r.SuperMoney = WST_CFGInt(n, "supermoney", 0);
				r.Coupons = WST_CFGInt(n, "coupons", 0);
				if (r.ItemID) cfg.ProgressRows.push_back(r);
			}
		}
	}

	YAML::Node task = root["task_base"];
	if (task)
	{
		cfg.Task.EntryID = WST_CFGInt(task, "entryID", WST_CFGInt(task, "entry_id", cfg.Task.EntryID));
		cfg.Task.BgPicPath = WST_CFGString(task, "BgPicPath", WST_CFGString(task, "bg_pic_path", cfg.Task.BgPicPath));
		cfg.Task.DateBeginStr = WST_CFGString(task, "DateBeginStr", WST_CFGString(task, "date_begin_str", "2026-06-01 00-00-00"));
		cfg.Task.DateEndStr = WST_CFGString(task, "DateEndStr", WST_CFGString(task, "date_end_str", "2026-08-02 23-59-59"));
		cfg.Task.HuodongName = WST_CFGString(task, "HuodongName", WST_CFGString(task, "huodong_name", "源·废土集结令"));
		cfg.Task.Describe = WST_CFGString(task, "Describe", WST_CFGString(task, "describe"));
		cfg.Task.HuodongRule = WST_CFGString(task, "HuodongRule", WST_CFGString(task, "huodong_rule"));
		cfg.Task.SeasonID = WST_CFGInt(task, "SeasonID", WST_CFGInt(task, "season_id", cfg.Task.SeasonID));
		cfg.Task.BeginTime = WST_CFGInt(task, "BeginTime", WST_CFGInt(task, "begin_time", cfg.Task.BeginTime));
		cfg.Task.EndTime = WST_CFGInt(task, "EndTime", WST_CFGInt(task, "end_time", cfg.Task.EndTime));
	}
	return cfg;
}

static const WSTStructActivityCfg* WST_StructFindActivity(const WSTStructRuntimeCfg& runtime, int activityType)
{
	const WSTStructActivityCfg* first = runtime.Activities.empty() ? nullptr : &runtime.Activities.front();
	for (size_t i = 0; i < runtime.Activities.size(); ++i)
	{
		if (runtime.Activities[i].ActivityType == activityType) return &runtime.Activities[i];
	}
	for (size_t i = 0; i < runtime.Activities.size(); ++i)
	{
		if (runtime.Activities[i].ActivityType == 2) return &runtime.Activities[i];
	}
	return first;
}

static std::vector<WSTStructItemCfg> WST_StructItemsFor(const std::vector<WSTStructItemCfg>& all, int activityType)
{
	std::vector<WSTStructItemCfg> out;
	for (size_t i = 0; i < all.size(); ++i)
	{
		if (all[i].ActivityType == activityType) out.push_back(all[i]);
	}
	return out;
}

static std::vector<WSTStructExchangeCfg> WST_StructExchangeFor(const WSTStructRuntimeCfg& runtime, int activityType)
{
	std::vector<WSTStructExchangeCfg> out;
	for (size_t i = 0; i < runtime.ExchangeRows.size(); ++i)
	{
		if (runtime.ExchangeRows[i].ActivityType == activityType) out.push_back(runtime.ExchangeRows[i]);
	}
	return out;
}

static std::vector<WSTStructProgressCfg> WST_StructProgressFor(const WSTStructRuntimeCfg& runtime, int activityType)
{
	std::vector<WSTStructProgressCfg> out;
	for (size_t i = 0; i < runtime.ProgressRows.size(); ++i)
	{
		if (runtime.ProgressRows[i].ActivityType == activityType) out.push_back(runtime.ProgressRows[i]);
	}
	return out;
}

static void WST_WriteUtf8TextValue(BYTE*& p, const char* key, const std::string& value)
{
	CT_WriteKey(p, key);
	std::string wire = HB_Utf8ToGbk(value);
	WriteText(p, wire.c_str(), static_cast<DWORD>(wire.size()));
	CT_ReserveQuickRpcRawTextForDict(wire);
}

static void WST_WriteStructActivityBase(BYTE*& p, const WSTStructActivityCfg& cfg)
{
	// Official Entrys baseCfg key order.
	CT_WriteTextNumber(p, "iCostItemID", static_cast<int>(cfg.CostItemID));
	CT_WriteTextNumber(p, "iCloseDate", cfg.CloseDate);
	CT_WriteTextNumber(p, "iCostNum50Time", cfg.CostFifty);
	CT_WriteTextNumber(p, "iCloseTime", cfg.CloseTime);
	CT_WriteTextNumber(p, "iOpenTime", cfg.OpenTime);
	CT_WriteTextNumber(p, "burst_baoji", cfg.BurstBaoji);
	CT_WriteTextNumber(p, "exchangeBestItemID", static_cast<int>(cfg.BestPieceItemID));
	CT_WriteTextNumber(p, "iFenJieItemID", static_cast<int>(cfg.FenjieItemID));
	CT_WriteTextNumber(p, "iOpenDate", cfg.OpenDate);
	CT_WriteTextNumber(p, "iCostNum10Time", cfg.CostTen);
	CT_WriteTextNumber(p, "iCostNumOneTime", cfg.CostOne);
	CT_WriteTextNumber(p, "iSeasonId", cfg.SeasonID);
	WST_WriteUtf8TextValue(p, "SubTitleDesc", cfg.SubTitle);
}

static void WST_WriteStructEntrysPayload(BYTE*& p, const WSTStructRuntimeCfg& runtime)
{
	for (size_t i = 0; i < runtime.Activities.size(); ++i)
	{
		const WSTStructActivityCfg& cfg = runtime.Activities[i];
		CT_WriteIndexedObject(p, cfg.ActivityType, [&](BYTE*& item) {
			WST_WriteBool(item, "isOpen", true);
			WST_WriteUtf8TextValue(item, "ActivityName", cfg.Name);
			CT_WriteKey(item, "baseCfg");
			BYTE* baseLen = CT_WriteLenValueStart(item);
			BYTE* baseStart = item;
			WST_WriteStructActivityBase(item, cfg);
			CT_WriteLenValueEnd(baseLen, baseStart, item);
			CT_WriteTextNumber(item, "ActivityType", cfg.ActivityType);
		});
	}
}

static int WST_StructHaveItem(std::shared_ptr<ClientNode> Client, UINT itemID)
{
	return (Client && itemID) ? PlayerDB_GetItemNum(Client->Uin, itemID) : 0;
}

static int WST_StructCostForDraw(const WSTStructActivityCfg& cfg, int drawCount)
{
	if (drawCount >= 50) return cfg.CostFifty;
	if (drawCount >= 10) return cfg.CostTen;
	return cfg.CostOne;
}

static int WST_StructFirstCommonNeedRemain(std::shared_ptr<ClientNode> Client, const WSTStructRuntimeCfg& runtime, const WSTStructActivityCfg& cfg)
{
	std::vector<WSTStructExchangeCfg> rows = WST_StructExchangeFor(runtime, cfg.ActivityType);
	if (rows.empty()) return 0;

	int fenjieRemain = -1;
	int minRemain = 2147483647;
	for (size_t c = 0; c < rows.front().Costs.size(); ++c)
	{
		const WSTStructCostCfg& cost = rows.front().Costs[c];
		int remain = std::max(0, cost.NeedNum - WST_StructHaveItem(Client, cost.PieceID));
		if (remain == 0) return 0;
		if (cost.PieceID == cfg.FenjieItemID) fenjieRemain = remain;
		if (remain < minRemain) minRemain = remain;
	}
	if (fenjieRemain >= 0) return fenjieRemain;
	return minRemain == 2147483647 ? 0 : minRemain;
}

static void WST_WriteStructInfoData(BYTE*& p, std::shared_ptr<ClientNode> Client, const WSTStructRuntimeCfg& runtime, const WSTStructActivityCfg& cfg, const WastelandStateRow& state)
{
	// Official Info data block key order; award pool and score rewards are tail FD blocks.
	CT_WriteTextNumber(p, "exchangeBestItemID", static_cast<int>(cfg.BestPieceItemID));
	CT_WriteTextNumber(p, "RemindItemId", static_cast<int>(cfg.RemindItemID));
	CT_WriteTextNumber(p, "DecNum50Time", 0);
	CT_WriteTextNumber(p, "burst_baoji", cfg.BurstBaoji);
	CT_WriteTextNumber(p, "CostItemNum", WST_StructHaveItem(Client, cfg.CostItemID));
	CT_WriteTextNumber(p, "iOpenTime", cfg.OpenTime);
	CT_WriteTextNumber(p, "iCloseTime", cfg.CloseTime);
	CT_WriteTextNumber(p, "AccuScore", state.DrawCount);
	WST_WriteUtf8TextValue(p, "SubTitleDesc", cfg.SubTitle);
	CT_WriteTextNumber(p, "iCostItemID", static_cast<int>(cfg.CostItemID));
	CT_WriteTextNumber(p, "DecNumOneTime", 0);
	CT_WriteTextNumber(p, "iCostNumOneTime", cfg.CostOne);
	CT_WriteTextNumber(p, "iFenJieItemID", static_cast<int>(cfg.FenjieItemID));
	CT_WriteTextNumber(p, "SplNeedExchangeItemNum", WST_StructFirstCommonNeedRemain(Client, runtime, cfg));
	CT_WriteTextNumber(p, "FenJieTotalNum", WST_StructHaveItem(Client, cfg.FenjieItemID));
	CT_WriteTextNumber(p, "DecNum10Time", 0);
	CT_WriteTextNumber(p, "RemindType", 1);
	CT_WriteTextNumber(p, "iOpenDate", cfg.OpenDate);
	CT_WriteTextNumber(p, "iCostNum10Time", cfg.CostTen);
	CT_WriteTextNumber(p, "iCostNum50Time", cfg.CostFifty);
	CT_WriteTextNumber(p, "iSeasonId", cfg.SeasonID);
	CT_WriteTextNumber(p, "iCloseDate", cfg.CloseDate);
}

static void WST_WriteStructInfoAwardBlock(BYTE*& p, const std::vector<WSTStructItemCfg>& awards)
{
	for (size_t i = 0; i < awards.size(); ++i)
	{
		const WSTStructItemCfg& r = awards[i];
		CT_WriteIndexedObject(p, r.Index > 0 ? r.Index : static_cast<int>(i + 1), [&](BYTE*& item) {
			CT_WriteTextNumber(item, "availperiod", r.AvailPeriod);
			CT_WriteTextNumber(item, "exchangeNeedNum", r.ExchangeNeedNum);
			CT_WriteTextNumber(item, "award_idx", r.AwardIdx);
			CT_WriteTextNumber(item, "itemnum", r.ItemNum);
			CT_WriteTextNumber(item, "item_type", r.ItemType);
			CT_WriteTextNumber(item, "coupons", r.Coupons);
			CT_WriteTextNumber(item, "supermoney", r.SuperMoney);
			CT_WriteTextNumber(item, "fenjie_num", r.FenjieNum);
			CT_WriteTextNumber(item, "itemid", static_cast<int>(r.ItemID));
		});
	}
}

static void WST_WriteStructProgressBlock(BYTE*& p, const std::vector<WSTStructProgressCfg>& rows, const WastelandStateRow& state)
{
	for (size_t i = 0; i < rows.size(); ++i)
	{
		const WSTStructProgressCfg& r = rows[i];
		UINT bit = r.SpecialFlag > 0 ? (1u << static_cast<UINT>(r.SpecialFlag - 1)) : 0;
		int status = (bit && (state.ClaimMask & bit)) ? 2 : (state.DrawCount >= r.NeedScore ? 1 : 0);
		CT_WriteIndexedObject(p, r.Index > 0 ? r.Index : static_cast<int>(i + 1), [&](BYTE*& item) {
			CT_WriteKey(item, "item");
			BYTE* listLen = CT_WriteLenValueStart(item);
			BYTE* listStart = item;
			CT_WriteIndexedObject(item, 1, [&](BYTE*& award) {
				CT_WriteTextNumber(award, "m_iAvailPeriod", r.AvailPeriod);
				CT_WriteTextNumber(award, "m_ushItemType", r.ItemType);
				CT_WriteTextNumber(award, "m_iSuperMoney", r.SuperMoney);
				CT_WriteTextNumber(award, "m_iItemNum", r.ItemNum);
				CT_WriteTextNumber(award, "m_iCoupons", r.Coupons);
				CT_WriteTextNumber(award, "m_iItemID", static_cast<int>(r.ItemID));
			});
			CT_WriteLenValueEnd(listLen, listStart, item);
			CT_WriteTextNumber(item, "status", status);
			CT_WriteTextNumber(item, "needScore", r.NeedScore);
			CT_WriteTextNumber(item, "specialFlag", r.SpecialFlag);
		});
	}
}

static void WST_WriteStructInfoTail(BYTE*& p, const WSTStructRuntimeCfg& runtime, const WSTStructActivityCfg& cfg, const WastelandStateRow& state)
{
	std::vector<WSTStructItemCfg> awards = WST_StructItemsFor(runtime.InfoAwards, cfg.ActivityType);
	BYTE* poolLen = CT_WriteLenValueStart(p);
	BYTE* poolStart = p;
	WST_WriteStructInfoAwardBlock(p, awards);
	CT_WriteLenValueEnd(poolLen, poolStart, p);

	std::vector<WSTStructProgressCfg> progress = WST_StructProgressFor(runtime, cfg.ActivityType);
	BYTE* progressLen = CT_WriteLenValueStart(p);
	BYTE* progressStart = p;
	WST_WriteStructProgressBlock(p, progress, state);
	CT_WriteLenValueEnd(progressLen, progressStart, p);
}

static void WST_WriteStructPieceCountFlatTail(BYTE*& p, std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg)
{
	BYTE* len = CT_WriteLenValueStart(p);
	BYTE* start = p;
	WriteValue(p, static_cast<int>(cfg.FenjieItemID));
	WriteValue(p, WST_StructHaveItem(Client, cfg.FenjieItemID));
	WriteValue(p, static_cast<int>(cfg.BestPieceItemID));
	WriteValue(p, WST_StructHaveItem(Client, cfg.BestPieceItemID));
	CT_WriteLenValueEnd(len, start, p);
}

static void WST_WriteStructPieceCountIndexedTail(BYTE*& p, std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg)
{
	BYTE* len = CT_WriteLenValueStart(p);
	BYTE* start = p;
	CT_WriteIndexedObject(p, 1, [&](BYTE*& item) {
		CT_WriteTextNumber(item, "itemnum", WST_StructHaveItem(Client, cfg.FenjieItemID));
		CT_WriteTextNumber(item, "itemid", static_cast<int>(cfg.FenjieItemID));
	});
	CT_WriteIndexedObject(p, 2, [&](BYTE*& item) {
		CT_WriteTextNumber(item, "itemnum", WST_StructHaveItem(Client, cfg.BestPieceItemID));
		CT_WriteTextNumber(item, "itemid", static_cast<int>(cfg.BestPieceItemID));
	});
	CT_WriteLenValueEnd(len, start, p);
}

static int WST_ExchangeStatus(std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg, const WSTStructExchangeCfg& row)
{
	int getNum = Client ? PlayerDB_WSTGetExchangeCount(Client->Uin, cfg.ActivityType, row.AwardIdx) : 0;
	if (row.MaxGetNum > 0 && getNum >= row.MaxGetNum) return 2;
	if (row.Costs.empty()) return 0;
	for (size_t i = 0; i < row.Costs.size(); ++i)
	{
		if (WST_StructHaveItem(Client, row.Costs[i].PieceID) >= row.Costs[i].NeedNum) return 1;
	}
	return 0;
}

static void WST_WriteStructExchangeData(BYTE*& p, std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg, const std::vector<WSTStructExchangeCfg>& rows)
{
	for (size_t i = 0; i < rows.size(); ++i)
	{
		const WSTStructExchangeCfg& r = rows[i];
		int getNum = Client ? PlayerDB_WSTGetExchangeCount(Client->Uin, cfg.ActivityType, r.AwardIdx) : 0;
		int status = WST_ExchangeStatus(Client, cfg, r);
		CT_WriteIndexedObject(p, r.Index > 0 ? r.Index : static_cast<int>(i + 1), [&](BYTE*& item) {
			CT_WriteTextNumber(item, "availperiod", r.AvailPeriod);
			CT_WriteTextNumber(item, "errid", r.ErrID);
			if (i == 0) CT_WriteTextNumber(item, "getnum", getNum);
			CT_WriteTextNumber(item, "maxGetNum", r.MaxGetNum);
			if (i == 0) CT_WriteTextNumber(item, "remindFlag", r.RemindFlag);
			if (i > 0) CT_WriteTextNumber(item, "award_idx", r.AwardIdx);
			CT_WriteTextNumber(item, "itemnum", r.ItemNum);
			CT_WriteTextNumber(item, "item_type", r.ItemType);
			if (i == 0)
			{
				CT_WriteKey(item, "genderitem");
				BYTE* genderLen = CT_WriteLenValueStart(item);
				BYTE* genderStart = item;
				WriteValue(item, 1);
				WriteValue(item, static_cast<int>(r.ItemID));
				CT_WriteLenValueEnd(genderLen, genderStart, item);
				CT_WriteTextNumber(item, "status", status);
				CT_WriteTextNumber(item, "award_idx", r.AwardIdx);
			}
			else
			{
				CT_WriteTextNumber(item, "status", status);
				CT_WriteTextNumber(item, "getnum", getNum);
				CT_WriteKey(item, "genderitem");
				BYTE* genderLen = CT_WriteLenValueStart(item);
				BYTE* genderStart = item;
				WriteValue(item, 1);
				WriteValue(item, static_cast<int>(r.ItemID));
				CT_WriteLenValueEnd(genderLen, genderStart, item);
			}
			CT_WriteKey(item, "exchange_items");
			BYTE* costLen = CT_WriteLenValueStart(item);
			BYTE* costStart = item;
			for (size_t c = 0; c < r.Costs.size(); ++c)
			{
				const WSTStructCostCfg& cost = r.Costs[c];
				CT_WriteIndexedObject(item, static_cast<int>(c + 1), [&](BYTE*& one) {
					CT_WriteTextNumber(one, "exchangePieceID", static_cast<int>(cost.PieceID));
					CT_WriteTextNumber(one, "exchangeNeedNum", std::max(0, cost.NeedNum));
				});
			}
			CT_WriteLenValueEnd(costLen, costStart, item);
		});
	}
}

struct WSTStructTempBoxViewRow
{
	UINT ItemID = 0;
	int ItemType = 0;
	int AvailPeriod = 0;
	int FenjieNum = 0;
	int ItemNum = 0;
	int GetNum = 0;
	int DecomposeNum = 0;
};

static void WST_AddStructTempBoxViewRow(std::vector<WSTStructTempBoxViewRow>& viewRows, const WastelandTempItemRow& raw)
{
	if (raw.ItemID == 0) return;
	int itemNum = raw.ItemNum > 0 ? raw.ItemNum : 1;
	int itemType = raw.ItemType;
	int fenjieNum = raw.FenjieNum;
	for (size_t i = 0; i < viewRows.size(); ++i)
	{
		WSTStructTempBoxViewRow& row = viewRows[i];
		if (row.ItemID == raw.ItemID &&
			row.ItemType == itemType &&
			row.AvailPeriod == raw.AvailPeriod &&
			row.FenjieNum == fenjieNum)
		{
			if (raw.Status == 1) row.GetNum += itemNum;
			else if (raw.Status == 2) row.DecomposeNum += itemNum;
			else row.ItemNum += itemNum;
			return;
		}
	}

	WSTStructTempBoxViewRow row;
	row.ItemID = raw.ItemID;
	row.ItemType = itemType;
	row.AvailPeriod = raw.AvailPeriod;
	row.FenjieNum = fenjieNum;
	if (raw.Status == 1) row.GetNum = itemNum;
	else if (raw.Status == 2) row.DecomposeNum = itemNum;
	else row.ItemNum = itemNum;
	viewRows.push_back(row);
}

static std::vector<WSTStructTempBoxViewRow> WST_BuildStructTempBoxViewRows(const std::vector<WastelandTempItemRow>& rows)
{
	std::vector<WSTStructTempBoxViewRow> viewRows;
	for (size_t i = 0; i < rows.size(); ++i)
	{
		WST_AddStructTempBoxViewRow(viewRows, rows[i]);
	}
	return viewRows;
}

static void WST_WriteStructTempBoxData(BYTE*& p, std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg)
{
	std::vector<WastelandTempItemRow> rows;
	if (Client) PlayerDB_WSTLoadTempItems(Client->Uin, cfg.ActivityType, rows, -1);

	std::vector<WSTStructTempBoxViewRow> viewRows = WST_BuildStructTempBoxViewRows(rows);

	for (size_t i = 0; i < viewRows.size(); ++i)
	{
		const WSTStructTempBoxViewRow& r = viewRows[i];
		CT_WriteIndexedObject(p, static_cast<int>(i + 1), [&](BYTE*& item) {
			CT_WriteTextNumber(item, "ItemNum", r.ItemNum);
			CT_WriteTextNumber(item, "GetNum", r.GetNum);
			CT_WriteTextNumber(item, "DecomposeNum", r.DecomposeNum);
			CT_WriteTextNumber(item, "Available", r.AvailPeriod);
			CT_WriteTextNumber(item, "fenjie_num", r.FenjieNum);
			CT_WriteTextNumber(item, "ItemType", r.ItemType);
			CT_WriteTextNumber(item, "ItemId1", 0);
			CT_WriteTextNumber(item, "ItemId", static_cast<int>(r.ItemID));
		});
	}
}

static WSTStructItemCfg WST_StructPickDrawAward(const WSTStructRuntimeCfg& runtime, const WSTStructActivityCfg& cfg)
{
	std::vector<WSTStructItemCfg> pool = WST_StructItemsFor(runtime.DrawPool, cfg.ActivityType);
	if (pool.empty()) pool = WST_StructItemsFor(runtime.InfoAwards, cfg.ActivityType);
	if (pool.empty())
	{
		WSTStructItemCfg fallback;
		fallback.ActivityType = cfg.ActivityType;
		fallback.Index = 1;
		fallback.AwardIdx = 1;
		fallback.ItemID = cfg.FenjieItemID ? cfg.FenjieItemID : cfg.CostItemID;
		fallback.ItemNum = 1;
		return fallback;
	}
	int total = 0;
	for (size_t i = 0; i < pool.size(); ++i) total += std::max(1, pool[i].Weight);
	int roll = total > 0 ? (rand() % total) : 0;
	for (size_t i = 0; i < pool.size(); ++i)
	{
		roll -= std::max(1, pool[i].Weight);
		if (roll < 0) return pool[i];
	}
	return pool.back();
}

static bool WST_IsPriorityDrawAward(const WSTStructItemCfg& award)
{
	return award.ToTempBox || award.ItemType == 1 || award.ItemType == 2;
}

