static void WST_StructGrantAward(std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg, const WSTStructItemCfg& award, std::vector<ItemInfo>* notifyItems = nullptr)
{
	if (!Client || award.ItemID == 0 || award.ItemNum <= 0) return;
	if (award.ToTempBox)
	{
		WastelandTempItemRow row;
		row.ActivityType = cfg.ActivityType;
		row.AwardIdx = award.AwardIdx;
		row.ItemID = award.ItemID;
		row.ItemNum = award.ItemNum;
		row.ItemType = award.ItemType;
		row.AvailPeriod = award.AvailPeriod;
		row.FenjieNum = award.FenjieNum;
		row.Status = 0;
		PlayerDB_WSTAddTempItem(Client->Uin, cfg.ActivityType, row);
		return;
	}
	int finalNum = PlayerDB_AddItem2(Client, Client->Uin, award.ItemID, award.ItemNum, award.AvailPeriod, false);
	int notifyType = award.ItemType > 0 ? award.ItemType : static_cast<int>(GetItemType(award.ItemID));
	int notifyNum = finalNum > 0 ? finalNum : award.ItemNum;
	if (notifyItems)
	{
		notifyItems->push_back(WST_MakeNotifyItem(award.ItemID, notifyNum, award.AvailPeriod, notifyType));
	}
	else
	{
		CT_SendAddItemNotify(Client, static_cast<int>(award.ItemID), notifyNum, award.AvailPeriod, notifyType);
	}
}

