static bool WST_TempRequestMatchesRaw(const WSTTempItemRequest& request, const WastelandTempItemRow& raw)
{
	const WastelandTempItemRow& row = request.Row;
	if (!WST_TempReqHasMinimumItem(request)) return false;
	if (raw.ItemID != row.ItemID) return false;
	if (raw.ItemType != row.ItemType) return false;
	if (raw.AvailPeriod != row.AvailPeriod) return false;
	if (request.HasFenjieNum && raw.FenjieNum != row.FenjieNum) return false;
	return true;
}

static bool WST_SelectedTempRowIdExists(const std::vector<UINT>& selectedIds, UINT id)
{
	return id > 0 && std::find(selectedIds.begin(), selectedIds.end(), id) != selectedIds.end();
}

static bool WST_SelectPendingTempItems(std::shared_ptr<ClientNode> Client, const WSTStructActivityCfg& cfg, const std::vector<WSTTempItemRequest>& requests, std::vector<WastelandTempItemRow>& selected, int& invalidReqs, int& missingReqs)
{
	selected.clear();
	invalidReqs = 0;
	missingReqs = 0;
	if (!Client || requests.empty()) return false;
	std::vector<WastelandTempItemRow> rows;
	PlayerDB_WSTLoadTempItems(Client->Uin, cfg.ActivityType, rows, 0);
	if (rows.empty()) return false;
	std::vector<UINT> selectedIds;

	for (size_t r = 0; r < requests.size(); ++r)
	{
		const WSTTempItemRequest& request = requests[r];
		if (!WST_TempReqHasMinimumItem(request))
		{
			++invalidReqs;
			continue;
		}
		std::vector<WastelandTempItemRow> candidates;
		if (request.HasId && request.Row.Id > 0)
		{
			for (size_t i = 0; i < rows.size(); ++i)
			{
				if (rows[i].Id == request.Row.Id && WST_TempRequestMatchesRaw(request, rows[i]))
				{
					candidates.push_back(rows[i]);
					break;
				}
			}
		}
		else
		{
			for (size_t i = 0; i < rows.size(); ++i)
			{
				if (WST_TempRequestMatchesRaw(request, rows[i])) candidates.push_back(rows[i]);
			}
		}
		int remain = (request.HasItemNum && request.Row.ItemNum > 0) ? request.Row.ItemNum : 0x3fffffff;
		bool resolved = false;
		for (size_t i = 0; i < candidates.size() && remain > 0; ++i)
		{
			const WastelandTempItemRow& row = candidates[i];
			if (WST_SelectedTempRowIdExists(selectedIds, row.Id)) continue;
			selected.push_back(row);
			if (row.Id > 0) selectedIds.push_back(row.Id);
			remain -= std::max(1, row.ItemNum);
			resolved = true;
		}
		if (!resolved) ++missingReqs;
	}
	return !selected.empty();
}

