template <typename Writer>
static void ZY_WriteFdBlock(BYTE*& p, Writer writer)
{
	BYTE* len = CT_WriteLenValueStart(p);
	BYTE* start = p;
	writer(p);
	CT_WriteLenValueEnd(len, start, p);
}


static bool ZY_PatchNumberAfterTextKey(BYTE* start, BYTE* end, const char* key, double value)
{
	if (!start || !end || !key) return false;
	size_t keyLen = strlen(key);
	if (keyLen == 0 || keyLen > 0x7f) return false;
	for (BYTE* p = start; p + 2 + keyLen + 9 <= end; ++p)
	{
		if (p[0] == 0xFA && p[1] == static_cast<BYTE>(keyLen) && memcmp(p + 2, key, keyLen) == 0)
		{
			BYTE* v = p + 2 + keyLen;
			if (v < end && *v == 0xF6)
			{
				memcpy(v + 1, &value, sizeof(double));
				return true;
			}
		}
	}
	return false;
}

static bool ZY_SendOfficialBody(std::shared_ptr<ClientNode> Client, double context, const char* bodyHex, const char* tag, int costItemNum = -1, int accuScore = -1)
{
	if (!Client || !bodyHex || !*bodyHex) return false;
	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	size_t len = 0;
	{
		BYTE* pHead = p;
		Write16(pHead, 0);
		Write32(pHead, Client->Uin);
		Write32(pHead, (DWORD)time(nullptr));
		Write8(pHead, 0);
		Write8(pHead, 0);
		Write8(pHead, 0);
		len = pHead - p;
		Set16(p, (WORD)len);
		p += len;
	}
	{
		BYTE* pBody = p;
		Write16(pBody, 0);
		BYTE* pMsgLen = pBody;
		Write16(pBody, 0);
		BYTE* pMsgStart = pBody;
		BYTE* pData = pMsgStart;
		WriteHex(pData, bodyHex);
		if ((pData - pMsgStart) >= 29 && pMsgStart[20] == 0xF6)
		{
			memcpy(pMsgStart + 21, &context, sizeof(double));
		}
		if (costItemNum >= 0) ZY_PatchNumberAfterTextKey(pMsgStart, pData, "CostItemNum", static_cast<double>(costItemNum));
		if (accuScore >= 0) ZY_PatchNumberAfterTextKey(pMsgStart, pData, "AccuScore", static_cast<double>(accuScore));
		Set16(pMsgLen, static_cast<WORD>(pData - pMsgStart));
		Write16(pData, 0);
		len = pData - p;
		Set16(p, (WORD)len);
		p += len;
	}
	Write32(p, 0);
	len = p - buf.data();
	SendToClient(Client, 24251, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);
	QQS_DebugPrintf10001("[ZhiYao] OfficialRaw %s Uin=%u Context=%.0f BodyLen=%zu SendLen=%zu\n", tag ? tag : "", Client->Uin, context, strlen(bodyHex) / 2, len);
	return true;
}

