	ZY_SendOfficialBody(Client, 0, kZY_OfficialCostNotifyBodyHex, "CostNotify");
	if (ZY_SendOfficialBody(Client, context, kZY_OfficialInfoBodyHex, "TemplateInfo", PlayerDB_GetItemNum(Client->Uin, costItemID), state.AccuScore)) return;
