// AwardOpt opt=1 draw result; source=绘梦1次_获得潮动足球发饰_ pkt=8
static const char* kHM_OfficialDrawBodyHex = R"HEX()HEX";

// AwardOpt opt=9 gift; source=绘梦人生_打开特惠礼包 pkt=1
static const char* kHM_OfficialGiftBodyHex = R"HEX()HEX";

// AwardOpt opt=10 buy card; source=购买_绘梦卡卷 pkt=10
static const char* kHM_OfficialBuyCardBodyHex = R"HEX()HEX";

static bool HM_PatchNumberAfterTextKey(BYTE* start, BYTE* end, const char* key, double value)
{
	if (!start || !end || !key) return false;
	size_t keyLen = strlen(key);
	if (keyLen == 0 || keyLen > 0x7f) return false;
	for (BYTE* p = start; p + 2 + keyLen + 9 <= end; ++p)
	{
		if (p[0] == 0xFA && p[1] == static_cast<BYTE>(keyLen) && memcmp(p + 2, key, keyLen) == 0)
		{
			BYTE* v = p + 2 + keyLen;
			if (v < end && *v == 0xF6)
			{
				memcpy(v + 1, &value, sizeof(double));
				return true;
			}
		}
	}
	return false;
}

static bool HM_SendOfficialBody(std::shared_ptr<ClientNode> Client, double context, const char* bodyHex, const char* tag, int costItemNum = -1, int drawCount = -1)
{
	if (!Client || !bodyHex || !*bodyHex) return false;
	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	size_t len = 0;
	{
		BYTE* pHead = p;
		Write16(pHead, 0);
		Write32(pHead, Client->Uin);
		Write32(pHead, (DWORD)time(nullptr));
		Write8(pHead, 0);
		Write8(pHead, 0);
		Write8(pHead, 0);
		len = pHead - p;
		Set16(p, (WORD)len);
		p += len;
	}
	{
		BYTE* pBody = p;
		Write16(pBody, 0);
		BYTE* pMsgLen = pBody;
		Write16(pBody, 0);
		BYTE* pMsgStart = pBody;
		BYTE* pData = pMsgStart;
		WriteHex(pData, bodyHex);
		if ((pData - pMsgStart) >= 29 && pMsgStart[20] == 0xF6)
		{
			memcpy(pMsgStart + 21, &context, sizeof(double));
		}
		if (costItemNum >= 0) HM_PatchNumberAfterTextKey(pMsgStart, pData, "CostItemNum", static_cast<double>(costItemNum));
		if (drawCount >= 0)
		{
			HM_PatchNumberAfterTextKey(pMsgStart, pData, "DrawCount", static_cast<double>(drawCount));
			HM_PatchNumberAfterTextKey(pMsgStart, pData, "AccuScore", static_cast<double>(drawCount));
		}
		Set16(pMsgLen, static_cast<WORD>(pData - pMsgStart));
		Write16(pData, 0);
		len = pData - p;
		Set16(p, (WORD)len);
		p += len;
	}
	Write32(p, 0);
	len = p - buf.data();
	SendToClient(Client, 24251, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);
	QQS_DebugPrintf10001("[Huimeng] OfficialRaw %s Uin=%u Context=%.0f BodyLen=%zu SendLen=%zu CostItemNum=%d DrawCount=%d\n",
		tag ? tag : "", Client->Uin, context, strlen(bodyHex) / 2, len, costItemNum, drawCount);
	return true;
}

static void HM_SendCostNotEnough(std::shared_ptr<ClientNode> Client)
{
	HM_SendOfficialBody(Client, 0, kHM_OfficialCostNotifyBodyHex, "CostNotEnough");
}


