	INT CostTen = 10;
	INT CostFifty = 50;
	INT DisabledResultCode = 1;
	bool StrictDrawCost = true;
	bool BuyCardFree = true;
	bool UseReplayDraws = false;
	INT BaoJiBaseCount = 50;
	INT ProgressClaimOp = 4;
	INT ScoreAwardCount = 0;
	INT GiftPackCount = 0;
	std::string ConfigPath;
