struct TarotAwardCfg
{
	INT Idx = 0;
	UINT ItemID = 0;
	INT ItemNum = 1;
	INT ItemType = 0;
	INT AvailPeriod = 0;
	INT ShowPriority = 1;
	INT PoolA = 0;
	INT PoolB = 0;
	INT Weight = 1;
	INT ZancunFlag = 0;
	INT SpecialType = 1;
	INT Score = 1;
	INT CardIdx = 0;
	INT MaxScore = 0;
	INT KartGrooveNum = 0;
	INT FenjieNum = 1;
	INT GetNum = 0;
};

struct TarotPageCfg
{
	INT Page = 1;
	INT ActivityType = 1;
	std::string Name = "命运塔罗-芒星";
	std::vector<TarotAwardCfg> AwardPool;
	std::vector<TarotAwardCfg> DestinyPool;
};

struct TarotReplayDrawCfg
{
	INT DrawNo = 0;
	std::vector<TarotAwardCfg> Items;
};

struct TarotConditionRewardCfg
{
	INT Id = 0;
	std::string Name;
	std::string ConditionType = "draw_count";
	INT ConditionValue = 0;
	INT Page = 0;
	std::vector<TarotAwardCfg> Rewards;
};

struct TarotRuntimeCfg
{
	bool Enabled = true;
	bool StrictCost = false;
	bool ConsumeIfPresent = true;
	bool UseReplayDraws = true;
	INT DisabledResultCode = 1;
	UINT ActivityId = 20260516;
	INT SeasonId = 1;
	INT BeginTime = 1775232000;
	INT EndTime = 1779033599;
	INT CostItemID = 154033;
	INT CostOne = 1;
	INT CostTen = 10;
	INT CostFifty = 50;
	INT UnlockFifty = 400;
	INT ScorePerDraw = 1;
	std::string ConfigPath;
	std::vector<TarotPageCfg> Pages;
	std::vector<TarotReplayDrawCfg> ReplayDraws;
	std::vector<TarotConditionRewardCfg> ConditionRewards;
};

static TarotAwardCfg TC_MakeAward(INT idx, UINT itemID, INT itemNum, INT itemType, INT availPeriod, INT showPriority, INT poolB, INT zancunFlag = 0, INT specialType = 1, INT cardIdx = 0, INT maxScore = 0)
{
	TarotAwardCfg row;
	row.Idx = idx;
	row.ItemID = itemID;
	row.ItemNum = itemNum > 0 ? itemNum : 1;
	row.ItemType = itemType;
	row.AvailPeriod = availPeriod;
	row.ShowPriority = showPriority;
	row.PoolA = poolB > 0 ? 1 : 0;
	row.PoolB = poolB;
	row.Weight = 1;
	row.ZancunFlag = zancunFlag;
	row.SpecialType = specialType;
	row.Score = 1;
	row.CardIdx = cardIdx > 0 ? cardIdx : poolB;
	row.MaxScore = maxScore;
	row.FenjieNum = 1;
	return row;
}

