static YAML::Node TC_LoadRootNode(std::string& loadedPath)
{
	const char* paths[] = { ".\\24251\\Tarot.yml", ".\\Config\\Tarot.yml" };
	for (const char* path : paths)
	{
		try
		{
			YAML::Node doc = YAML::LoadFile(path);
			loadedPath = path;
			if (doc["tarot"]) return doc["tarot"];
			return doc;
		}
		catch (const std::exception&) {}
	}
	loadedPath.clear();
	return YAML::Node();
}

static TarotAwardCfg TC_AwardFromNode(const YAML::Node& node, INT fallbackIdx)
{
	TarotAwardCfg row;
	row.Idx = CT_YIntAny(node, { "idx", "index", "award_idx", "_index" }, fallbackIdx);
	row.ItemID = static_cast<UINT>(CT_YIntAny(node, { "item_id", "itemid", "itemId", "m_iItemID", "id" }, 0));
	row.ItemNum = CT_YIntAny(node, { "item_num", "itemnum", "itemNum", "m_iItemNum", "num" }, 1);
	row.ItemType = CT_YIntAny(node, { "item_type", "itemType", "m_ushItemType" }, 0);
	row.AvailPeriod = CT_YIntAny(node, { "avail_period", "availperiod", "period", "m_iAvailPeriod" }, 0);
	row.ShowPriority = CT_YIntAny(node, { "show_priority", "showPriority", "m_usShowPriority" }, fallbackIdx);
	row.PoolA = CT_YIntAny(node, { "pool_a", "poolA" }, 0);
	row.PoolB = CT_YIntAny(node, { "pool_b", "poolB", "card_idx", "cardIdx", "randomCardsIdx" }, 0);
	if (node["pool"] && node["pool"].IsSequence())
	{
		row.PoolA = node["pool"].size() > 0 ? node["pool"][0].as<int>(row.PoolA) : row.PoolA;
		row.PoolB = node["pool"].size() > 1 ? node["pool"][1].as<int>(row.PoolB) : row.PoolB;
	}
	row.Weight = CT_YIntAny(node, { "weight", "probability" }, 1);
	row.ZancunFlag = CT_YIntAny(node, { "zancun_flag", "zancunFlag" }, 0);
	row.SpecialType = CT_YIntAny(node, { "special_type", "specialType" }, row.ZancunFlag ? 2 : 1);
	row.Score = CT_YIntAny(node, { "score", "randomScore", "add_score" }, 1);
	row.CardIdx = CT_YIntAny(node, { "card_idx", "cardIdx", "randomCardsIdx" }, row.PoolB);
	row.MaxScore = CT_YIntAny(node, { "max_score", "maxScore" }, 0);
	row.KartGrooveNum = CT_YIntAny(node, { "kart_groove_num", "kartGrooveNum", "groove_num", "grooveNum" }, 0);
	row.FenjieNum = CT_YIntAny(node, { "fenjie_num", "fenjieNum", "m_iFenjieNum" }, 1);
	row.GetNum = CT_YIntAny(node, { "get_num", "getNum", "m_iGetNum" }, 0);
	if (row.CardIdx <= 0 && row.PoolB > 0) row.CardIdx = row.PoolB;
	if (row.ItemID > 0 && row.ItemType < 0) row.ItemType = static_cast<int>(GetItemType(row.ItemID));
	return row;
}

static std::vector<TarotAwardCfg> TC_AwardsFromSeq(const YAML::Node& seq)
{
	std::vector<TarotAwardCfg> rows;
	if (!seq || !seq.IsSequence()) return rows;
	INT idx = 1;
	for (const auto& node : seq)
	{
		TarotAwardCfg row = TC_AwardFromNode(node, idx++);
		if (row.ItemID > 0) rows.push_back(row);
	}
	return rows;
}

static TarotRuntimeCfg TC_LoadRuntimeCfg()
{
	TarotRuntimeCfg cfg = TC_DefaultCfg();
	try
	{
		std::string path;
		YAML::Node root = TC_LoadRootNode(path);
		if (!root) return cfg;
		cfg.ConfigPath = path;
		cfg.Enabled = GWB_YBoolAny(root, { "enabled" }, cfg.Enabled);
		cfg.StrictCost = GWB_YBoolAny(root, { "strict_cost", "strictCost" }, cfg.StrictCost);
		cfg.ConsumeIfPresent = GWB_YBoolAny(root, { "consume_if_present", "consumeIfPresent" }, cfg.ConsumeIfPresent);
		cfg.UseReplayDraws = GWB_YBoolAny(root, { "use_replay_draws", "useReplayDraws" }, cfg.UseReplayDraws);
		cfg.DisabledResultCode = CT_YIntAny(root, { "disabled_result_code", "disabledResultCode" }, cfg.DisabledResultCode);
		cfg.ActivityId = static_cast<UINT>(CT_YIntAny(root, { "activity_id", "activityId" }, static_cast<int>(cfg.ActivityId)));
		cfg.SeasonId = CT_YIntAny(root, { "season_id", "seasonId" }, cfg.SeasonId);
		YAML::Node timeNode = root["time"] ? root["time"] : root["activity_time"];
		cfg.BeginTime = CT_YIntAny(timeNode, { "begin_time", "beginTime", "BeginTime" }, CT_YIntAny(root, { "begin_time", "beginTime", "BeginTime" }, cfg.BeginTime));
		cfg.EndTime = CT_YIntAny(timeNode, { "end_time", "endTime", "EndTime" }, CT_YIntAny(root, { "end_time", "endTime", "EndTime" }, cfg.EndTime));
		YAML::Node cost = root["cost"];
		cfg.CostItemID = CT_YIntAny(cost, { "item_id", "itemId", "draw_item_id", "drawItemId" }, CT_YIntAny(root, { "draw_item_id", "drawItemId", "cost_item_id" }, cfg.CostItemID));
		cfg.CostOne = CT_YIntAny(cost, { "one", "once", "iCostNumOneTime" }, cfg.CostOne);
		cfg.CostTen = CT_YIntAny(cost, { "ten", "iCostNum10Time" }, cfg.CostTen);
		cfg.CostFifty = CT_YIntAny(cost, { "fifty", "iCostNum50Time" }, cfg.CostFifty);
		cfg.UnlockFifty = CT_YIntAny(cost, { "unlock_fifty", "unlockFifty", "iUnlockNum50Time" }, cfg.UnlockFifty);
		cfg.ScorePerDraw = CT_YIntAny(root["draw"], { "score_per_draw", "scorePerDraw" }, CT_YIntAny(root, { "score_per_draw", "scorePerDraw" }, cfg.ScorePerDraw));

		YAML::Node pages = root["pages"];
		if (pages && pages.IsSequence())
		{
			cfg.Pages.clear();
			for (const auto& pnode : pages)
			{
				TarotPageCfg page;
				page.Page = CT_YIntAny(pnode, { "page", "type", "activity_type", "ActivityType" }, static_cast<int>(cfg.Pages.size() + 1));
				page.ActivityType = CT_YIntAny(pnode, { "activity_type", "ActivityType" }, page.Page);
				page.Name = FB_YStringAny(pnode, { "name", "activity_name", "ActivityName" }, page.Name);
				page.AwardPool = TC_AwardsFromSeq(pnode["award_pool"] ? pnode["award_pool"] : pnode["pool4"]);
				page.DestinyPool = TC_AwardsFromSeq(pnode["destiny_pool"] ? pnode["destiny_pool"] : pnode["pool5"]);
				cfg.Pages.push_back(page);
			}
		}

		YAML::Node replay = root["replay_draws"];
		if (replay && replay.IsSequence())
		{
			cfg.ReplayDraws.clear();
			INT fallbackDrawNo = 1;
			for (const auto& rnode : replay)
			{
				TarotReplayDrawCfg row;
				row.DrawNo = CT_YIntAny(rnode, { "draw_no", "drawNo", "round" }, fallbackDrawNo++);
				if (rnode["items"] && rnode["items"].IsSequence()) row.Items = TC_AwardsFromSeq(rnode["items"]);
				else
				{
					TarotAwardCfg award = TC_AwardFromNode(rnode, row.DrawNo);
					if (award.ItemID > 0) row.Items.push_back(award);
				}
				if (!row.Items.empty()) cfg.ReplayDraws.push_back(row);
			}
		}

		YAML::Node cond = root["condition_rewards"];
		if (cond && cond.IsSequence())
		{
			cfg.ConditionRewards.clear();
			INT fallbackId = 1;
			for (const auto& cnode : cond)
			{
				TarotConditionRewardCfg cr;
				cr.Id = CT_YIntAny(cnode, { "id", "idx", "index", "_index" }, fallbackId++);
				cr.Name = FB_YStringAny(cnode, { "name" }, "");
				cr.ConditionType = FB_YStringAny(cnode, { "condition_type", "conditionType" }, "draw_count");
				cr.ConditionValue = CT_YIntAny(cnode, { "condition_value", "conditionValue", "need", "needActivityCount" }, 0);
				cr.Page = CT_YIntAny(cnode, { "page" }, 0);
				cr.Rewards = TC_AwardsFromSeq(cnode["rewards"] ? cnode["rewards"] : cnode["items"]);
				if (cr.Id > 0) cfg.ConditionRewards.push_back(cr);
			}
		}
	}
	catch (const std::exception& e)
	{
		QQS_DebugPrintf10001("[Tarot] Load Tarot.yml failed, use defaults: %s\n", e.what());
	}
	return cfg;
}

static const TarotPageCfg* TC_FindPage(const TarotRuntimeCfg& cfg, INT page)
{
	for (const auto& p : cfg.Pages) if (p.Page == page) return &p;
	return cfg.Pages.empty() ? nullptr : &cfg.Pages[0];
}

static UINT& TC_PageMaskRef(TarotStateRow& state, INT page)
{
	if (page == 2) return state.Page2CardMask;
	if (page == 3) return state.Page3CardMask;
	if (page == 4) return state.Page4CardMask;
	return state.Page1CardMask;
}

static UINT TC_PageMaskValue(const TarotStateRow& state, INT page)
{
	if (page == 2) return state.Page2CardMask;
	if (page == 3) return state.Page3CardMask;
	if (page == 4) return state.Page4CardMask;
	return state.Page1CardMask;
}

static INT TC_CountBits(UINT mask)
{
	INT count = 0;
	while (mask) { count += (mask & 1u) ? 1 : 0; mask >>= 1; }
	return count;
}

static INT TC_NextCardIdx(const TarotStateRow& state, INT page)
{
	UINT mask = TC_PageMaskValue(state, page);
	for (INT i = 1; i <= 16; ++i)
	{
		if ((mask & (1u << (i - 1))) == 0) return i;
	}
	return (state.DrawCount % 16) + 1;
}

static TarotStateRow TC_LoadStateOrDefault(std::shared_ptr<ClientNode> Client, const TarotRuntimeCfg& cfg)
{
	TarotStateRow state;
	state.ActivityId = cfg.ActivityId;
	state.MaxScore = 1;
	if (Client) PlayerDB_TarotLoadState(Client->Uin, cfg.ActivityId, state);
	if (state.CurDraw <= 0) state.CurDraw = state.DrawCount;
	if (state.DrawItemCnt < 0) state.DrawItemCnt = 0;
	if (state.MaxScore <= 0) state.MaxScore = state.CurScore > 0 ? state.CurScore : 1;
	return state;
}

static bool TC_IsConditionClaimed(const TarotStateRow& state, INT id)
{
	if (id <= 0 || id > 31) return false;
	return (state.AccuClaimMask & (1u << (id - 1))) != 0;
}

static void TC_SetConditionClaimed(TarotStateRow& state, INT id)
{
	if (id > 0 && id <= 31) state.AccuClaimMask |= (1u << (id - 1));
}

static bool TC_ConditionMet(const TarotStateRow& state, const TarotConditionRewardCfg& cr)
{
	if (_stricmp(cr.ConditionType.c_str(), "score") == 0)
	{
		INT score = state.CurScore > state.MaxScore ? state.CurScore : state.MaxScore;
		return score >= cr.ConditionValue;
	}
	if (_stricmp(cr.ConditionType.c_str(), "page_card_count") == 0)
	{
		INT page = cr.Page > 0 ? cr.Page : 1;
		return TC_CountBits(TC_PageMaskValue(state, page)) >= cr.ConditionValue;
	}
	if (_stricmp(cr.ConditionType.c_str(), "total_card_count") == 0)
	{
		INT total = TC_CountBits(state.Page1CardMask) + TC_CountBits(state.Page2CardMask) + TC_CountBits(state.Page3CardMask) + TC_CountBits(state.Page4CardMask);
		return total >= cr.ConditionValue;
	}
	return state.DrawCount >= cr.ConditionValue;
}

static const TarotConditionRewardCfg* TC_FindConditionReward(const TarotRuntimeCfg& cfg, INT id)
{
	for (const auto& cr : cfg.ConditionRewards) if (cr.Id == id) return &cr;
	return nullptr;
}

static std::vector<TarotConditionRewardCfg> TC_AccuRewardsForWire(const TarotRuntimeCfg& cfg)
{
	std::vector<TarotConditionRewardCfg> rows;
	rows.reserve(8);
	static const INT kOfficialNeeds[8] = { 2, 5, 8, 9, 11, 12, 14, 16 };
	for (INT i = 1; i <= 8; ++i)
	{
		const TarotConditionRewardCfg* src = TC_FindConditionReward(cfg, i);
		TarotConditionRewardCfg cr = src ? *src : TarotConditionRewardCfg();
		cr.Id = i;
		if (cr.Name.empty()) cr.Name = "累计翻开" + std::to_string(kOfficialNeeds[i - 1]) + "张";
		if (cr.ConditionType.empty()) cr.ConditionType = "draw_count";
		if (cr.ConditionValue <= 0) cr.ConditionValue = kOfficialNeeds[i - 1];
		if (cr.Rewards.empty()) cr.Rewards.push_back(TC_MakeAward(1, 154033, 1, 0, -1, 1, 0));
		rows.push_back(cr);
	}
	return rows;
}

static std::vector<TarotAwardCfg> TC_DrawAwardsForNo(const TarotRuntimeCfg& cfg, INT page, INT drawNo)
{
	if (cfg.UseReplayDraws)
	{
		for (const auto& row : cfg.ReplayDraws)
		{
			if (row.DrawNo == drawNo) return row.Items;
		}
		if (!cfg.ReplayDraws.empty() && drawNo > 0)
		{
			return cfg.ReplayDraws[(drawNo - 1) % cfg.ReplayDraws.size()].Items;
		}
	}
	const TarotPageCfg* pageCfg = TC_FindPage(cfg, page);
	std::vector<TarotAwardCfg> pool = pageCfg ? pageCfg->AwardPool : std::vector<TarotAwardCfg>();
	if (pool.empty()) return std::vector<TarotAwardCfg>();
	INT total = 0;
	for (const auto& r : pool) total += r.Weight > 0 ? r.Weight : 1;
	INT hit = static_cast<INT>((static_cast<UINT>(drawNo) * 1103515245u + static_cast<UINT>(page) * 12345u) % static_cast<UINT>(total > 0 ? total : 1));
	for (const auto& r : pool)
	{
		hit -= r.Weight > 0 ? r.Weight : 1;
		if (hit < 0) return { r };
	}
	return { pool.back() };
}

static void TC_WriteBoolValue(BYTE*& p, const char* key, bool value)
{
	CT_WriteKey(p, key);
	if (value) WriteF8(p); else WriteF9(p);
}

static void TC_WriteTextString(BYTE*& p, const char* key, const std::string& value)
{
	CT_WriteKey(p, key);
	std::string wire = HB_Utf8ToGbk(value);
	WriteText(p, wire.c_str(), static_cast<DWORD>(wire.size()));
	CT_ReserveQuickRpcRawTextForDict(wire);
}

static void TC_WritePoolAward(BYTE*& p, const TarotAwardCfg& row)
{
	CT_WriteTextNumber(p, "m_iAvailPeriod", row.AvailPeriod);
	CT_WriteTextNumber(p, "m_ushItemType", row.ItemType);
	CT_WriteKey(p, "pool");
	BYTE* poolLen = CT_WriteLenValueStart(p); BYTE* poolStart = p;
	if (row.PoolA > 0 || row.PoolB > 0)
	{
		WriteValue(p, row.PoolA > 0 ? row.PoolA : 1);
		WriteValue(p, row.PoolB);
	}
	CT_WriteLenValueEnd(poolLen, poolStart, p);
	CT_WriteTextNumber(p, "m_iItemNum", row.ItemNum > 0 ? row.ItemNum : 1);
	CT_WriteTextNumber(p, "m_iItemID", static_cast<int>(row.ItemID));
	CT_WriteTextNumber(p, "m_usShowPriority", row.ShowPriority);
}

static void TC_WriteAwardPool(BYTE*& p, const std::vector<TarotAwardCfg>& rows)
{
	for (size_t i = 0; i < rows.size(); ++i)
	{
		CT_WriteIndexedObject(p, static_cast<int>(i + 1), [&](BYTE*& item) { TC_WritePoolAward(item, rows[i]); });
	}
}

